INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g6_1_math_u3_L02_basic#1','math',6,1,'u3','L02','g6_1_math_u3_L02_basic','lesson_basic','M6-1-u3-C1',1,'sa','auto','6.8은 0.1이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u3-C1","difficulty":1,"kind":"sa","stem":"6.8은 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["68"],"explanation":["0.1이 10개이면 1이에요.","6.8은 6과 소수 부분을 합해 0.1이 68개예요.","그래서 6.8은 0.1이 68개인 수예요."],"mis":"M6-1-u3-X03","variant_rule":{"alt":[{"stem":"3.6은 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["0.1이 10개이면 1이에요.","3.6은 3과 소수 부분을 합해 0.1이 36개예요.","그래서 3.6은 0.1이 36개인 수예요."]},{"stem":"9.6은 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["96"],"explanation":["0.1이 10개이면 1이에요.","9.6은 9와 소수 부분을 합해 0.1이 96개예요.","그래서 9.6은 0.1이 96개인 수예요."]}]}}'::jsonb),
('g6_1_math_u3_L02_basic#2','math',6,1,'u3','L02','g6_1_math_u3_L02_basic','lesson_basic','M6-1-u3-C1',1,'mc','auto','648 ÷ 2 = 324예요. 그러면 64.8 ÷ 2의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":2,"concept":"M6-1-u3-C1","difficulty":1,"kind":"mc","stem":"648 ÷ 2 = 324예요. 그러면 64.8 ÷ 2의 몫은 얼마인가요?","options":[{"t":"32.4","correct":true},{"t":"324","mis":"M6-1-u3-X01"},{"t":"3.24","mis":"M6-1-u3-X02"},{"t":"3240","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 2는 그대로예요.","나누어지는 수 64.8은 648의 ⟨1/10⟩배예요.","그래서 몫도 324의 ⟨1/10⟩배 — 32.4예요."],"variant_rule":{"alt":[{"stem":"846 ÷ 2 = 423이에요. 그러면 84.6 ÷ 2의 몫은 얼마인가요?","options":[{"t":"42.3","correct":true},{"t":"423","mis":"M6-1-u3-X01"},{"t":"4.23","mis":"M6-1-u3-X02"},{"t":"4230","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 2는 그대로예요.","나누어지는 수 84.6은 846의 ⟨1/10⟩배예요.","그래서 몫도 423의 ⟨1/10⟩배 — 42.3이에요."]},{"stem":"936 ÷ 3 = 312예요. 그러면 93.6 ÷ 3의 몫은 얼마인가요?","options":[{"t":"31.2","correct":true},{"t":"312","mis":"M6-1-u3-X01"},{"t":"3.12","mis":"M6-1-u3-X02"},{"t":"3120","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 3은 그대로예요.","나누어지는 수 93.6은 936의 ⟨1/10⟩배예요.","그래서 몫도 312의 ⟨1/10⟩배 — 31.2예요."]}]}}'::jsonb),
('g6_1_math_u3_L02_basic#3','math',6,1,'u3','L02','g6_1_math_u3_L02_basic','lesson_basic','M6-1-u3-C1',1,'sa','auto','884 ÷ 26의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u3-C1","difficulty":1,"kind":"sa","stem":"884 ÷ 26의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["34"],"explanation":["자연수의 나눗셈은 높은 자리부터 나누고 남은 수를 다음 자리로 내려요.","34 × 26 = 884로 확인할 수 있어요.","884 ÷ 26 = 34예요."],"mis":"M6-1-u3-X13","variant_rule":{"alt":[{"stem":"765 ÷ 17의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["자연수의 나눗셈은 높은 자리부터 나누고 남은 수를 다음 자리로 내려요.","45 × 17 = 765로 확인할 수 있어요.","765 ÷ 17 = 45예요."]},{"stem":"882 ÷ 18의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["49"],"explanation":["자연수의 나눗셈은 높은 자리부터 나누고 남은 수를 다음 자리로 내려요.","49 × 18 = 882로 확인할 수 있어요.","882 ÷ 18 = 49예요."]}]}}'::jsonb),
('g6_1_math_u3_L02_basic#4','math',6,1,'u3','L02','g6_1_math_u3_L02_basic','lesson_basic','M6-1-u3-C1',1,'mc','auto','6.8 ÷ 2의 몫은 어느 두 수 사이에 있나요?',ARRAY['M6-1-u3-X12']::text[],true,'{"seq":4,"concept":"M6-1-u3-C1","difficulty":1,"kind":"mc","stem":"6.8 ÷ 2의 몫은 어느 두 수 사이에 있나요?","options":[{"t":"3과 4 사이","correct":true},{"t":"2와 3 사이","mis":"M6-1-u3-X12"},{"t":"4와 5 사이","mis":"M6-1-u3-X12"},{"t":"5와 6 사이","mis":"M6-1-u3-X12"}],"explanation":["6.8을 계산하기 쉬운 자연수로 바꾸어 어림해요.","6 ÷ 2 = 3이고 8 ÷ 2 = 4예요.","6.8은 6과 8 사이라 몫도 3과 4 사이예요."],"variant_rule":{"alt":[{"stem":"3.6 ÷ 3의 몫은 어느 두 수 사이에 있나요?","options":[{"t":"1과 2 사이","correct":true},{"t":"0과 1 사이","mis":"M6-1-u3-X12"},{"t":"2와 3 사이","mis":"M6-1-u3-X12"},{"t":"3과 4 사이","mis":"M6-1-u3-X12"}],"explanation":["3.6을 계산하기 쉬운 자연수로 바꾸어 어림해요.","3 ÷ 3 = 1이고 6 ÷ 3 = 2예요.","3.6은 3과 6 사이라 몫도 1과 2 사이예요."]},{"stem":"8.4 ÷ 4의 몫은 어느 두 수 사이에 있나요?","options":[{"t":"2와 3 사이","correct":true},{"t":"1과 2 사이","mis":"M6-1-u3-X12"},{"t":"3과 4 사이","mis":"M6-1-u3-X12"},{"t":"4와 5 사이","mis":"M6-1-u3-X12"}],"explanation":["8.4를 계산하기 쉬운 자연수로 바꾸어 어림해요.","8 ÷ 4 = 2이고 12 ÷ 4 = 3이에요.","8.4는 8과 12 사이라 몫도 2와 3 사이예요."]}]}}'::jsonb),
('g6_1_math_u3_L02_basic#5','math',6,1,'u3','L02','g6_1_math_u3_L02_basic','lesson_basic','M6-1-u3-C1',2,'sa','auto','6.8을 두 묶음으로 똑같이 나누어요. 한 묶음은 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u3-C1","difficulty":2,"kind":"sa","stem":"6.8을 두 묶음으로 똑같이 나누어요. 한 묶음은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["34"],"explanation":["6.8은 0.1이 68개인 수예요.","68 ÷ 2 = 34 — 한 묶음은 0.1이 34개예요.","0.1이 34개이면 3.4예요."],"mis":"M6-1-u3-X03","variant_rule":{"alt":[{"stem":"9.6을 세 묶음으로 똑같이 나누어요. 한 묶음은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["9.6은 0.1이 96개인 수예요.","96 ÷ 3 = 32 — 한 묶음은 0.1이 32개예요.","0.1이 32개이면 3.2예요."]},{"stem":"8.4를 네 묶음으로 똑같이 나누어요. 한 묶음은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["8.4는 0.1이 84개인 수예요.","84 ÷ 4 = 21 — 한 묶음은 0.1이 21개예요.","0.1이 21개이면 2.1이에요."]}]}}'::jsonb),
('g6_1_math_u3_L02_basic#6','math',6,1,'u3','L02','g6_1_math_u3_L02_basic','lesson_basic','M6-1-u3-C1',2,'mc','auto','488 ÷ 4 = 122예요. 그러면 4.88 ÷ 4의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":6,"concept":"M6-1-u3-C1","difficulty":2,"kind":"mc","stem":"488 ÷ 4 = 122예요. 그러면 4.88 ÷ 4의 몫은 얼마인가요?","options":[{"t":"1.22","correct":true},{"t":"12.2","mis":"M6-1-u3-X01"},{"t":"0.122","mis":"M6-1-u3-X02"},{"t":"122","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 4는 그대로예요.","나누어지는 수 4.88은 488의 ⟨1/100⟩배예요.","그래서 몫도 122의 ⟨1/100⟩배 — 1.22예요."],"variant_rule":{"alt":[{"stem":"393 ÷ 3 = 131이에요. 그러면 3.93 ÷ 3의 몫은 얼마인가요?","options":[{"t":"1.31","correct":true},{"t":"13.1","mis":"M6-1-u3-X01"},{"t":"0.131","mis":"M6-1-u3-X02"},{"t":"131","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 3은 그대로예요.","나누어지는 수 3.93은 393의 ⟨1/100⟩배예요.","그래서 몫도 131의 ⟨1/100⟩배 — 1.31이에요."]},{"stem":"846 ÷ 2 = 423이에요. 그러면 8.46 ÷ 2의 몫은 얼마인가요?","options":[{"t":"4.23","correct":true},{"t":"42.3","mis":"M6-1-u3-X01"},{"t":"0.423","mis":"M6-1-u3-X02"},{"t":"423","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 2는 그대로예요.","나누어지는 수 8.46은 846의 ⟨1/100⟩배예요.","그래서 몫도 423의 ⟨1/100⟩배 — 4.23이에요."]}]}}'::jsonb),
('g6_1_math_u3_L02_basic#7','math',6,1,'u3','L02','g6_1_math_u3_L02_basic','lesson_basic','M6-1-u3-C1',2,'mc','auto','3.6 ÷ 3을 분수의 나눗셈으로 바꾸어 계산하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X04','M6-1-u3-X03']::text[],true,'{"seq":7,"concept":"M6-1-u3-C1","difficulty":2,"kind":"mc","stem":"3.6 ÷ 3을 분수의 나눗셈으로 바꾸어 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨36/10⟩ × ⟨1/3⟩","correct":true},{"t":"⟨36/10⟩ × 3","mis":"M6-1-u3-X04"},{"t":"⟨10/36⟩ × ⟨1/3⟩","mis":"M6-1-u3-X04"},{"t":"⟨36/100⟩ × ⟨1/3⟩","mis":"M6-1-u3-X03"}],"explanation":["3.6은 ⟨36/10⟩이에요.","÷ 3은 × ⟨1/3⟩로 바꾸어 계산해요.","그래서 ⟨36/10⟩ × ⟨1/3⟩이에요."],"variant_rule":{"alt":[{"stem":"6.8 ÷ 2를 분수의 나눗셈으로 바꾸어 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨68/10⟩ × ⟨1/2⟩","correct":true},{"t":"⟨68/10⟩ × 2","mis":"M6-1-u3-X04"},{"t":"⟨10/68⟩ × ⟨1/2⟩","mis":"M6-1-u3-X04"},{"t":"⟨68/100⟩ × ⟨1/2⟩","mis":"M6-1-u3-X03"}],"explanation":["6.8은 ⟨68/10⟩이에요.","÷ 2는 × ⟨1/2⟩로 바꾸어 계산해요.","그래서 ⟨68/10⟩ × ⟨1/2⟩이에요."]},{"stem":"8.4 ÷ 4를 분수의 나눗셈으로 바꾸어 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨84/10⟩ × ⟨1/4⟩","correct":true},{"t":"⟨84/10⟩ × 4","mis":"M6-1-u3-X04"},{"t":"⟨10/84⟩ × ⟨1/4⟩","mis":"M6-1-u3-X04"},{"t":"⟨84/100⟩ × ⟨1/4⟩","mis":"M6-1-u3-X03"}],"explanation":["8.4는 ⟨84/10⟩예요.","÷ 4는 × ⟨1/4⟩로 바꾸어 계산해요.","그래서 ⟨84/10⟩ × ⟨1/4⟩이에요."]}]}}'::jsonb),
('g6_1_math_u3_L02_basic#8','math',6,1,'u3','L02','g6_1_math_u3_L02_basic','lesson_basic','M6-1-u3-C1',2,'ox','auto','6.8 ÷ 2는 0.1이 68개인 것을 둘로 나누는 것과 같아요.',ARRAY['M6-1-u3-X03']::text[],true,'{"seq":8,"concept":"M6-1-u3-C1","difficulty":2,"kind":"ox","stem":"6.8 ÷ 2는 0.1이 68개인 것을 둘로 나누는 것과 같아요.","answer":"O","reason_options":[{"t":"6.8은 0.1이 68개인 수이기 때문에","correct":true},{"t":"6.8은 0.1이 6개와 8개를 합한 수이기 때문에","mis":"M6-1-u3-X03"}],"mis":"M6-1-u3-X03","explanation":["소수는 0.1이나 0.01이 몇 개인 수로 볼 수 있어요.","나누는 수가 같을 때 나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배가 돼요.","분수의 나눗셈으로 바꾸면 ÷ 자연수는 × 자연수분의 1이에요."],"variant_rule":{"alt":[{"stem":"나누는 수가 같을 때 나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배가 돼요.","answer":"O","reason_options":[{"t":"나눌 양이 ⟨1/10⟩로 줄면 한 묶음의 양도 ⟨1/10⟩로 줄기 때문에","correct":true},{"t":"나누는 수가 같으면 몫도 언제나 같기 때문에","mis":"M6-1-u3-X01"}],"explanation":["소수는 0.1이나 0.01이 몇 개인 수로 볼 수 있어요.","나누는 수가 같을 때 나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배가 돼요.","분수의 나눗셈으로 바꾸면 ÷ 자연수는 × 자연수분의 1이에요."]},{"stem":"846 ÷ 2 = 423이면 84.6 ÷ 2 = 42.3이에요.","answer":"O","reason_options":[{"t":"84.6은 846의 ⟨1/10⟩배라서 몫도 ⟨1/10⟩배이기 때문에","correct":true},{"t":"나누어지는 수가 작아지면 몫은 커지기 때문에","mis":"M6-1-u3-X02"}],"explanation":["소수는 0.1이나 0.01이 몇 개인 수로 볼 수 있어요.","나누는 수가 같을 때 나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배가 돼요.","분수의 나눗셈으로 바꾸면 ÷ 자연수는 × 자연수분의 1이에요."]}]}}'::jsonb),
('g6_1_math_u3_L02_basic#9','math',6,1,'u3','L02','g6_1_math_u3_L02_basic','lesson_basic','M6-1-u3-C1',2,'mc','auto','걷기 대회 코스는 모두 6.8 km예요. 반환점은 코스의 정확히 절반 지점에 있어요. 반환점까지는 몇 km인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02','M6-1-u3-X10']::text[],true,'{"seq":9,"concept":"M6-1-u3-C1","difficulty":2,"kind":"mc","stem":"걷기 대회 코스는 모두 6.8 km예요. 반환점은 코스의 정확히 절반 지점에 있어요. 반환점까지는 몇 km인가요?","options":[{"t":"3.4 km","correct":true},{"t":"34 km","mis":"M6-1-u3-X01"},{"t":"0.34 km","mis":"M6-1-u3-X02"},{"t":"13.6 km","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 68 ÷ 2 = 34예요.","6.8은 68의 ⟨1/10⟩배라서 몫도 34의 ⟨1/10⟩배예요.","6.8 ÷ 2 = 3.4예요."],"variant_rule":{"alt":[{"stem":"길이가 3.6 m인 끈을 똑같이 잘라 기념품 상자 3개를 묶어요. 상자 한 개에 쓰는 끈은 몇 m인가요?","options":[{"t":"1.2 m","correct":true},{"t":"12 m","mis":"M6-1-u3-X01"},{"t":"0.12 m","mis":"M6-1-u3-X02"},{"t":"10.8 m","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 36 ÷ 3 = 12예요.","3.6은 36의 ⟨1/10⟩배라서 몫도 12의 ⟨1/10⟩배예요.","3.6 ÷ 3 = 1.2예요."]},{"stem":"리본 9.6 m를 세 명이 똑같이 나누어 가져요. 한 명이 가지는 리본은 몇 m인가요?","options":[{"t":"3.2 m","correct":true},{"t":"32 m","mis":"M6-1-u3-X01"},{"t":"0.32 m","mis":"M6-1-u3-X02"},{"t":"28.8 m","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 96 ÷ 3 = 32예요.","9.6은 96의 ⟨1/10⟩배라서 몫도 32의 ⟨1/10⟩배예요.","9.6 ÷ 3 = 3.2예요."]}]}}'::jsonb),
('g6_1_math_u3_L02_basic#10','math',6,1,'u3','L02','g6_1_math_u3_L02_basic','lesson_basic','M6-1-u3-C1',3,'sa','auto','리본 0.96 m를 세 명이 똑같이 나누어 가져요. 한 명이 가지는 리본은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u3-C1","difficulty":3,"kind":"sa","stem":"리본 0.96 m를 세 명이 똑같이 나누어 가져요. 한 명이 가지는 리본은 몇 cm인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["0.96 ÷ 3 = 0.32예요.","1 m는 100 cm예요.","0.32 m는 32 cm예요."],"mis":"M6-1-u3-X11","variant_rule":{"alt":[{"stem":"리본 0.84 m를 네 명이 똑같이 나누어 가져요. 한 명이 가지는 리본은 몇 cm인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["0.84 ÷ 4 = 0.21이에요.","1 m는 100 cm예요.","0.21 m는 21 cm예요."]},{"stem":"리본 0.69 m를 세 명이 똑같이 나누어 가져요. 한 명이 가지는 리본은 몇 cm인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["0.69 ÷ 3 = 0.23이에요.","1 m는 100 cm예요.","0.23 m는 23 cm예요."]}]}}'::jsonb),
('g6_1_math_u3_L02_challenge#1','math',6,1,'u3','L02','g6_1_math_u3_L02_challenge','lesson_challenge','M6-1-u3-C1',2,'mc','auto','684 ÷ 2 = 342예요. 그러면 68.4 ÷ 2의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":1,"concept":"M6-1-u3-C1","difficulty":2,"kind":"mc","stem":"684 ÷ 2 = 342예요. 그러면 68.4 ÷ 2의 몫은 얼마인가요?","options":[{"t":"34.2","correct":true},{"t":"342","mis":"M6-1-u3-X01"},{"t":"3.42","mis":"M6-1-u3-X02"},{"t":"3420","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 2는 그대로예요.","나누어지는 수 68.4는 684의 ⟨1/10⟩배예요.","그래서 몫도 342의 ⟨1/10⟩배 — 34.2예요."],"variant_rule":{"alt":[{"stem":"963 ÷ 3 = 321이에요. 그러면 96.3 ÷ 3의 몫은 얼마인가요?","options":[{"t":"32.1","correct":true},{"t":"321","mis":"M6-1-u3-X01"},{"t":"3.21","mis":"M6-1-u3-X02"},{"t":"3210","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 3은 그대로예요.","나누어지는 수 96.3은 963의 ⟨1/10⟩배예요.","그래서 몫도 321의 ⟨1/10⟩배 — 32.1이에요."]},{"stem":"488 ÷ 4 = 122예요. 그러면 48.8 ÷ 4의 몫은 얼마인가요?","options":[{"t":"12.2","correct":true},{"t":"122","mis":"M6-1-u3-X01"},{"t":"1.22","mis":"M6-1-u3-X02"},{"t":"1220","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 4는 그대로예요.","나누어지는 수 48.8은 488의 ⟨1/10⟩배예요.","그래서 몫도 122의 ⟨1/10⟩배 — 12.2예요."]}]}}'::jsonb),
('g6_1_math_u3_L02_challenge#2','math',6,1,'u3','L02','g6_1_math_u3_L02_challenge','lesson_challenge','M6-1-u3-C1',2,'mc','auto','1단원에서 배운 대로 계산하면 ⟨3/4⟩ ÷ 5는 얼마인가요?',ARRAY['M6-1-u3-X04','M6-1-u3-X13']::text[],true,'{"seq":2,"concept":"M6-1-u3-C1","difficulty":2,"kind":"mc","stem":"1단원에서 배운 대로 계산하면 ⟨3/4⟩ ÷ 5는 얼마인가요?","options":[{"t":"⟨3/20⟩","correct":true},{"t":"⟨15/4⟩","mis":"M6-1-u3-X04"},{"t":"⟨4/15⟩","mis":"M6-1-u3-X04"},{"t":"⟨3/9⟩","mis":"M6-1-u3-X13"}],"explanation":["÷ 5를 × ⟨1/5⟩로 바꾸어요.","⟨3/4⟩ × ⟨1/5⟩ = ⟨3/20⟩이에요.","분자는 그대로, 분모에 5를 곱했어요."],"variant_rule":{"alt":[{"stem":"1단원에서 배운 대로 계산하면 ⟨2/5⟩ ÷ 3은 얼마인가요?","options":[{"t":"⟨2/15⟩","correct":true},{"t":"⟨6/5⟩","mis":"M6-1-u3-X04"},{"t":"⟨5/6⟩","mis":"M6-1-u3-X04"},{"t":"⟨2/8⟩","mis":"M6-1-u3-X13"}],"explanation":["÷ 3을 × ⟨1/3⟩로 바꾸어요.","⟨2/5⟩ × ⟨1/3⟩ = ⟨2/15⟩예요.","분자는 그대로, 분모에 3을 곱했어요."]},{"stem":"1단원에서 배운 대로 계산하면 ⟨5/6⟩ ÷ 2는 얼마인가요?","options":[{"t":"⟨5/12⟩","correct":true},{"t":"⟨10/6⟩","mis":"M6-1-u3-X04"},{"t":"⟨6/10⟩","mis":"M6-1-u3-X04"},{"t":"⟨5/8⟩","mis":"M6-1-u3-X13"}],"explanation":["÷ 2를 × ⟨1/2⟩로 바꾸어요.","⟨5/6⟩ × ⟨1/2⟩ = ⟨5/12⟩예요.","분자는 그대로, 분모에 2를 곱했어요."]}]}}'::jsonb),
('g6_1_math_u3_L02_challenge#3','math',6,1,'u3','L02','g6_1_math_u3_L02_challenge','lesson_challenge','M6-1-u3-C1',3,'error','auto','648 ÷ 2 = 324를 이용해 64.8 ÷ 2를 계산하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X14']::text[],true,'{"seq":3,"concept":"M6-1-u3-C1","difficulty":3,"kind":"error","stem":"648 ÷ 2 = 324를 이용해 64.8 ÷ 2를 계산하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「나누어지는 수가 작아졌으니 몫은 324의 10배야.」","correct":true,"mis_target":"M6-1-u3-X01"},{"t":"이현 — 「64.8은 648의 ⟨1/10⟩배야.」","mis":"M6-1-u3-X14"},{"t":"서아 — 「몫은 32.4야.」","mis":"M6-1-u3-X14"}],"explanation":["나누는 수 2는 그대로예요.","나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배예요.","준희는 몫이 커진다고 거꾸로 말했어요."],"variant_rule":{"alt":[{"stem":"393 ÷ 3 = 131을 이용해 3.93 ÷ 3을 계산하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「나누어지는 수가 작아졌으니 몫은 131의 10배야.」","correct":true,"mis_target":"M6-1-u3-X01"},{"t":"수아 — 「3.93은 393의 ⟨1/100⟩배야.」","mis":"M6-1-u3-X14"},{"t":"도윤 — 「몫은 1.31이야.」","mis":"M6-1-u3-X14"}],"explanation":["나누는 수 3은 그대로예요.","나누어지는 수가 ⟨1/100⟩배가 되면 몫도 ⟨1/100⟩배예요.","서호는 몫이 커진다고 거꾸로 말했어요."]},{"stem":"846 ÷ 2 = 423을 이용해 84.6 ÷ 2를 계산하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「나누어지는 수가 작아졌으니 몫은 423의 10배야.」","correct":true,"mis_target":"M6-1-u3-X01"},{"t":"나린 — 「84.6은 846의 ⟨1/10⟩배야.」","mis":"M6-1-u3-X14"},{"t":"유진 — 「몫은 42.3이야.」","mis":"M6-1-u3-X14"}],"explanation":["나누는 수 2는 그대로예요.","나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배예요.","가온은 몫이 커진다고 거꾸로 말했어요."]}]}}'::jsonb),
('g6_1_math_u3_L02_challenge#4','math',6,1,'u3','L02','g6_1_math_u3_L02_challenge','lesson_challenge','M6-1-u3-C1',3,'mc','auto','둘레가 8.48 m인 정사각형 모양이 있어요. 한 변의 길이는 몇 m인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02','M6-1-u3-X10']::text[],true,'{"seq":4,"concept":"M6-1-u3-C1","difficulty":3,"kind":"mc","stem":"둘레가 8.48 m인 정사각형 모양이 있어요. 한 변의 길이는 몇 m인가요?","options":[{"t":"2.12 m","correct":true},{"t":"21.2 m","mis":"M6-1-u3-X01"},{"t":"0.212 m","mis":"M6-1-u3-X02"},{"t":"33.92 m","mis":"M6-1-u3-X10"}],"explanation":["정사각형은 4개의 변의 길이가 모두 같아요.","한 변의 길이는 둘레를 변의 수로 나누어 구해요.","8.48 ÷ 4 = 2.12예요."],"variant_rule":{"alt":[{"stem":"둘레가 99.63 cm인 정삼각형 모양이 있어요. 한 변의 길이는 몇 cm인가요?","options":[{"t":"33.21 cm","correct":true},{"t":"332.1 cm","mis":"M6-1-u3-X01"},{"t":"3.321 cm","mis":"M6-1-u3-X02"},{"t":"298.89 cm","mis":"M6-1-u3-X10"}],"explanation":["정삼각형은 3개의 변의 길이가 모두 같아요.","한 변의 길이는 둘레를 변의 수로 나누어 구해요.","99.63 ÷ 3 = 33.21이에요."]},{"stem":"둘레가 12.5 m인 정오각형 모양이 있어요. 한 변의 길이는 몇 m인가요?","options":[{"t":"2.5 m","correct":true},{"t":"25 m","mis":"M6-1-u3-X01"},{"t":"0.25 m","mis":"M6-1-u3-X02"},{"t":"62.5 m","mis":"M6-1-u3-X10"}],"explanation":["정오각형은 5개의 변의 길이가 모두 같아요.","한 변의 길이는 둘레를 변의 수로 나누어 구해요.","12.5 ÷ 5 = 2.5예요."]}]}}'::jsonb),
('g6_1_math_u3_L02_challenge#5','math',6,1,'u3','L02','g6_1_math_u3_L02_challenge','lesson_challenge','M6-1-u3-C1',3,'ox','auto','648 ÷ 2 = 324이면 6.48 ÷ 2 = 32.4예요.',ARRAY['M6-1-u3-X02']::text[],true,'{"seq":5,"concept":"M6-1-u3-C1","difficulty":3,"kind":"ox","stem":"648 ÷ 2 = 324이면 6.48 ÷ 2 = 32.4예요.","answer":"X","reason_options":[{"t":"6.48은 648의 ⟨1/100⟩배라서 몫도 ⟨1/100⟩배인 3.24이기 때문에","correct":true},{"t":"나누어지는 수의 소수점을 한 칸만 옮기면 되기 때문에","mis":"M6-1-u3-X02"}],"mis":"M6-1-u3-X02","explanation":["소수는 0.1이나 0.01이 몇 개인 수로 볼 수 있어요.","나누는 수가 같을 때 나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배가 돼요.","분수의 나눗셈으로 바꾸면 ÷ 자연수는 × 자연수분의 1이에요."],"variant_rule":{"alt":[{"stem":"3.6 ÷ 3은 ⟨36/10⟩ × 3으로 계산해요.","answer":"X","reason_options":[{"t":"÷ 3은 × ⟨1/3⟩로 바꾸어야 하기 때문에","correct":true},{"t":"÷ 자연수는 × 자연수로 바꾸기 때문에","mis":"M6-1-u3-X04"}],"explanation":["소수는 0.1이나 0.01이 몇 개인 수로 볼 수 있어요.","나누는 수가 같을 때 나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배가 돼요.","분수의 나눗셈으로 바꾸면 ÷ 자연수는 × 자연수분의 1이에요."]},{"stem":"9.6 ÷ 3의 몫은 3보다 커요.","answer":"O","reason_options":[{"t":"9.6은 9보다 크니 몫도 9 ÷ 3 = 3보다 크기 때문에","correct":true},{"t":"9.6은 소수라서 몫이 1보다 작기 때문에","mis":"M6-1-u3-X12"}],"explanation":["소수는 0.1이나 0.01이 몇 개인 수로 볼 수 있어요.","나누는 수가 같을 때 나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배가 돼요.","분수의 나눗셈으로 바꾸면 ÷ 자연수는 × 자연수분의 1이에요."]}]}}'::jsonb),
('g6_1_math_u3_L02_challenge#6','math',6,1,'u3','L02','g6_1_math_u3_L02_challenge','lesson_challenge','M6-1-u3-C1',3,'mc','auto','쌀 84.88 kg을 자루 4개에 똑같이 나누어 담았어요. 자루 한 개에 담긴 쌀은 몇 kg인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02','M6-1-u3-X10']::text[],true,'{"seq":6,"concept":"M6-1-u3-C1","difficulty":3,"kind":"mc","stem":"쌀 84.88 kg을 자루 4개에 똑같이 나누어 담았어요. 자루 한 개에 담긴 쌀은 몇 kg인가요?","options":[{"t":"21.22 kg","correct":true},{"t":"212.2 kg","mis":"M6-1-u3-X01"},{"t":"2.122 kg","mis":"M6-1-u3-X02"},{"t":"339.52 kg","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 8488 ÷ 4 = 2122예요.","84.88은 8488의 ⟨1/100⟩배라서 몫도 2122의 ⟨1/100⟩배예요.","84.88 ÷ 4 = 21.22예요."],"variant_rule":{"alt":[{"stem":"쌀 48.84 kg을 자루 4개에 똑같이 나누어 담았어요. 자루 한 개에 담긴 쌀은 몇 kg인가요?","options":[{"t":"12.21 kg","correct":true},{"t":"122.1 kg","mis":"M6-1-u3-X01"},{"t":"1.221 kg","mis":"M6-1-u3-X02"},{"t":"195.36 kg","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 4884 ÷ 4 = 1221이에요.","48.84는 4884의 ⟨1/100⟩배라서 몫도 1221의 ⟨1/100⟩배예요.","48.84 ÷ 4 = 12.21이에요."]},{"stem":"쌀 88.48 kg을 자루 4개에 똑같이 나누어 담았어요. 자루 한 개에 담긴 쌀은 몇 kg인가요?","options":[{"t":"22.12 kg","correct":true},{"t":"221.2 kg","mis":"M6-1-u3-X01"},{"t":"2.212 kg","mis":"M6-1-u3-X02"},{"t":"353.92 kg","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 8848 ÷ 4 = 2212예요.","88.48은 8848의 ⟨1/100⟩배라서 몫도 2212의 ⟨1/100⟩배예요.","88.48 ÷ 4 = 22.12예요."]}]}}'::jsonb),
('g6_1_math_u3_L02_challenge#7','math',6,1,'u3','L02','g6_1_math_u3_L02_challenge','lesson_challenge','M6-1-u3-C1',3,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u3-C1","difficulty":3,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"64.8 ÷ 2","r":"32.4"},{"l":"3.93 ÷ 3","r":"1.31"},{"l":"4.88 ÷ 4","r":"1.22"}],"mis":"M6-1-u3-X02","explanation":["자연수의 나눗셈으로 몫을 구한 뒤 같은 배율만큼 작게 해요.","64.8 ÷ 2 = 32.4, 3.93 ÷ 3 = 1.31, 4.88 ÷ 4 = 1.22예요.","어림한 값과 견주어 소수점 자리를 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"84.6 ÷ 2","r":"42.3"},{"l":"9.36 ÷ 3","r":"3.12"},{"l":"48.8 ÷ 4","r":"12.2"}],"explanation":["자연수의 나눗셈으로 몫을 구한 뒤 같은 배율만큼 작게 해요.","84.6 ÷ 2 = 42.3, 9.36 ÷ 3 = 3.12, 48.8 ÷ 4 = 12.2예요.","어림한 값과 견주어 소수점 자리를 확인해요."]},{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"6.48 ÷ 2","r":"3.24"},{"l":"39.3 ÷ 3","r":"13.1"},{"l":"8.84 ÷ 4","r":"2.21"}],"explanation":["자연수의 나눗셈으로 몫을 구한 뒤 같은 배율만큼 작게 해요.","6.48 ÷ 2 = 3.24, 39.3 ÷ 3 = 13.1, 8.84 ÷ 4 = 2.21이에요.","어림한 값과 견주어 소수점 자리를 확인해요."]}]}}'::jsonb),
('g6_1_math_u3_L02_challenge#8','math',6,1,'u3','L02','g6_1_math_u3_L02_challenge','lesson_challenge','M6-1-u3-C1',4,'mc','auto','846 ÷ 2의 몫은 8.46 ÷ 2의 몫의 몇 배인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":8,"concept":"M6-1-u3-C1","difficulty":4,"kind":"mc","stem":"846 ÷ 2의 몫은 8.46 ÷ 2의 몫의 몇 배인가요?","options":[{"t":"100배","correct":true},{"t":"10배","mis":"M6-1-u3-X01"},{"t":"1000배","mis":"M6-1-u3-X01"},{"t":"⟨1/10⟩배","mis":"M6-1-u3-X02"}],"explanation":["두 나눗셈은 나누는 수 2가 같아요.","나누어지는 수 846은 8.46의 100배예요.","그래서 몫도 100배예요 — 423과 4.23이에요."],"variant_rule":{"alt":[{"stem":"4.88 ÷ 4의 몫은 48.8 ÷ 4의 몫의 몇 배인가요?","options":[{"t":"⟨1/10⟩배","correct":true},{"t":"10배","mis":"M6-1-u3-X01"},{"t":"100배","mis":"M6-1-u3-X01"},{"t":"1000배","mis":"M6-1-u3-X01"}],"explanation":["두 나눗셈은 나누는 수 4가 같아요.","나누어지는 수 4.88은 48.8의 ⟨1/10⟩배예요.","그래서 몫도 ⟨1/10⟩배예요 — 1.22와 12.2예요."]},{"stem":"3.93 ÷ 3의 몫은 393 ÷ 3의 몫의 몇 배인가요?","options":[{"t":"⟨1/100⟩배","correct":true},{"t":"10배","mis":"M6-1-u3-X01"},{"t":"100배","mis":"M6-1-u3-X01"},{"t":"1000배","mis":"M6-1-u3-X01"}],"explanation":["두 나눗셈은 나누는 수 3이 같아요.","나누어지는 수 3.93은 393의 ⟨1/100⟩배예요.","그래서 몫도 ⟨1/100⟩배예요 — 1.31과 131이에요."]}]}}'::jsonb),
('g6_1_math_u3_L02_challenge#9','math',6,1,'u3','L02','g6_1_math_u3_L02_challenge','lesson_challenge','M6-1-u3-C1',4,'sa','auto','2.48을 네 묶음으로 똑같이 나누어요. 한 묶음은 0.01이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u3-C1","difficulty":4,"kind":"sa","stem":"2.48을 네 묶음으로 똑같이 나누어요. 한 묶음은 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["62"],"explanation":["2.48은 0.01이 248개인 수예요.","248 ÷ 4 = 62 — 한 묶음은 0.01이 62개예요.","0.01이 62개이면 0.62예요."],"mis":"M6-1-u3-X03","variant_rule":{"alt":[{"stem":"1.86을 세 묶음으로 똑같이 나누어요. 한 묶음은 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["62"],"explanation":["1.86은 0.01이 186개인 수예요.","186 ÷ 3 = 62 — 한 묶음은 0.01이 62개예요.","0.01이 62개이면 0.62예요."]},{"stem":"2.94를 세 묶음으로 똑같이 나누어요. 한 묶음은 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["98"],"explanation":["2.94는 0.01이 294개인 수예요.","294 ÷ 3 = 98 — 한 묶음은 0.01이 98개예요.","0.01이 98개이면 0.98이에요."]}]}}'::jsonb),
('g6_1_math_u3_L02_challenge#10','math',6,1,'u3','L02','g6_1_math_u3_L02_challenge','lesson_challenge','M6-1-u3-C1',4,'essay','teacher','걷기 대회 코스는 6.8 km이고 반환점은 코스의 정확히 절반 지점에 있어요. 반환점까지의 거리를 「0.1이 몇 개」로 생각하여 구하고, 그 거리가 몇 m인지도 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u3-C1","difficulty":4,"kind":"essay","stem":"걷기 대회 코스는 6.8 km이고 반환점은 코스의 정확히 절반 지점에 있어요. 반환점까지의 거리를 「0.1이 몇 개」로 생각하여 구하고, 그 거리가 몇 m인지도 써 보세요.","answer_guide":{"answer":"예: 6.8은 0.1이 68개인 수이다. 68개를 둘로 똑같이 나누면 34개이고, 0.1이 34개이면 3.4이므로 반환점까지는 3.4 km이다. 1 km는 1000 m이므로 3.4 km는 3400 m이다.","scoring_points":["6.8을 0.1이 68개로 보았는가","68 ÷ 2 = 34로 3.4 km를 구했는가","3400 m로 바꾸었는가"]},"explanation":["6.8은 0.1이 68개예요.","68 ÷ 2 = 34 — 3.4 km예요.","3.4 km는 3400 m예요."]}'::jsonb),
('g6_1_math_u3_L03_basic#1','math',6,1,'u3','L03','g6_1_math_u3_L03_basic','lesson_basic','M6-1-u3-C2',1,'mc','auto','492 ÷ 4 = 123이에요. 그러면 49.2 ÷ 4의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":1,"concept":"M6-1-u3-C2","difficulty":1,"kind":"mc","stem":"492 ÷ 4 = 123이에요. 그러면 49.2 ÷ 4의 몫은 얼마인가요?","options":[{"t":"12.3","correct":true},{"t":"123","mis":"M6-1-u3-X01"},{"t":"1.23","mis":"M6-1-u3-X02"},{"t":"1230","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 4는 그대로예요.","나누어지는 수 49.2는 492의 ⟨1/10⟩배예요.","그래서 몫도 123의 ⟨1/10⟩배 — 12.3이에요."],"variant_rule":{"alt":[{"stem":"1379 ÷ 7 = 197이에요. 그러면 13.79 ÷ 7의 몫은 얼마인가요?","options":[{"t":"1.97","correct":true},{"t":"19.7","mis":"M6-1-u3-X01"},{"t":"0.197","mis":"M6-1-u3-X02"},{"t":"197","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 7은 그대로예요.","나누어지는 수 13.79는 1379의 ⟨1/100⟩배예요.","그래서 몫도 197의 ⟨1/100⟩배 — 1.97이에요."]},{"stem":"585 ÷ 5 = 117이에요. 그러면 58.5 ÷ 5의 몫은 얼마인가요?","options":[{"t":"11.7","correct":true},{"t":"117","mis":"M6-1-u3-X01"},{"t":"1.17","mis":"M6-1-u3-X02"},{"t":"1170","mis":"M6-1-u3-X01"}],"explanation":["나누는 수 5는 그대로예요.","나누어지는 수 58.5는 585의 ⟨1/10⟩배예요.","그래서 몫도 117의 ⟨1/10⟩배 — 11.7이에요."]}]}}'::jsonb),
('g6_1_math_u3_L03_basic#2','math',6,1,'u3','L03','g6_1_math_u3_L03_basic','lesson_basic','M6-1-u3-C2',1,'mc','auto','11.7 ÷ 3의 몫은 얼마인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":2,"concept":"M6-1-u3-C2","difficulty":1,"kind":"mc","stem":"11.7 ÷ 3의 몫은 얼마인가요?","options":[{"t":"3.9","correct":true},{"t":"39","mis":"M6-1-u3-X01"},{"t":"0.39","mis":"M6-1-u3-X02"},{"t":"390","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 117 ÷ 3 = 39예요.","11.7은 117의 ⟨1/10⟩배라서 몫도 39의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 11.7 ÷ 3 = 3.9예요."],"variant_rule":{"alt":[{"stem":"34.5 ÷ 5의 몫은 얼마인가요?","options":[{"t":"6.9","correct":true},{"t":"69","mis":"M6-1-u3-X01"},{"t":"0.69","mis":"M6-1-u3-X02"},{"t":"690","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 345 ÷ 5 = 69예요.","34.5는 345의 ⟨1/10⟩배라서 몫도 69의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 34.5 ÷ 5 = 6.9예요."]},{"stem":"49.2 ÷ 4의 몫은 얼마인가요?","options":[{"t":"12.3","correct":true},{"t":"123","mis":"M6-1-u3-X01"},{"t":"1.23","mis":"M6-1-u3-X02"},{"t":"1230","mis":"M6-1-u3-X01"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 492 ÷ 4 = 123이에요.","49.2는 492의 ⟨1/10⟩배라서 몫도 123의 ⟨1/10⟩배예요.","몫의 소수점은 나누어지는 수의 소수점 위에 맞추어 올려 찍어요 — 49.2 ÷ 4 = 12.3이에요."]}]}}'::jsonb),
