('g6_1_math_u3_L06_challenge#4','math',6,1,'u3','L06','g6_1_math_u3_L06_challenge','lesson_challenge','M6-1-u3-C5',3,'ox','auto','9.05와 9.5는 같은 수예요.',ARRAY['M6-1-u3-X07']::text[],true,'{"seq":4,"concept":"M6-1-u3-C5","difficulty":3,"kind":"ox","stem":"9.05와 9.5는 같은 수예요.","answer":"X","reason_options":[{"t":"9.05의 0은 소수 첫째 자리를 지키는 숫자라 두 수는 다르기 때문에","correct":true},{"t":"가운데 0은 없어도 되는 숫자이기 때문에","mis":"M6-1-u3-X07"}],"mis":"M6-1-u3-X07","explanation":["수를 내려도 나누어야 할 수가 나누는 수보다 작으면 몫에 0을 써요.","그리고 수를 하나 더 내려 계산을 이어 가요.","이 0을 빠뜨리면 전혀 다른 수가 돼요."],"variant_rule":{"alt":[{"stem":"12.3 ÷ 6의 몫의 소수 첫째 자리 숫자는 0이에요.","answer":"O","reason_options":[{"t":"12.3 ÷ 6 = 2.05이기 때문에","correct":true},{"t":"12 ÷ 6 = 2라서 첫째 자리는 비어 있기 때문에","mis":"M6-1-u3-X07"}],"explanation":["수를 내려도 나누어야 할 수가 나누는 수보다 작으면 몫에 0을 써요.","그리고 수를 하나 더 내려 계산을 이어 가요.","이 0을 빠뜨리면 전혀 다른 수가 돼요."]},{"stem":"16.4 ÷ 8의 몫은 2.05예요.","answer":"O","reason_options":[{"t":"1640 ÷ 8 = 205이고 16.4는 1640의 ⟨1/100⟩배이기 때문에","correct":true},{"t":"16 ÷ 8 = 2이고 4 ÷ 8 = 0.5이기 때문에","mis":"M6-1-u3-X07"}],"explanation":["수를 내려도 나누어야 할 수가 나누는 수보다 작으면 몫에 0을 써요.","그리고 수를 하나 더 내려 계산을 이어 가요.","이 0을 빠뜨리면 전혀 다른 수가 돼요."]}]}}'::jsonb),
