('g6_1_math_u3_review_d#12','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C6',2,'mc','auto','9 ÷ 6의 몫은 얼마인가요?',ARRAY['M6-1-u3-X08','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":12,"concept":"M6-1-u3-C6","difficulty":2,"kind":"mc","stem":"9 ÷ 6의 몫은 얼마인가요?","options":[{"t":"1.5","correct":true},{"t":"1.3","mis":"M6-1-u3-X08"},{"t":"15","mis":"M6-1-u3-X01"},{"t":"0.15","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 90 ÷ 6 = 15예요.","9는 90의 ⟨1/10⟩배라서 몫도 15의 ⟨1/10⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 9 ÷ 6 = 1.5예요."],"variant_rule":{"alt":[{"stem":"60 ÷ 8의 몫은 얼마인가요?","options":[{"t":"7.5","correct":true},{"t":"7.4","mis":"M6-1-u3-X08"},{"t":"75","mis":"M6-1-u3-X01"},{"t":"0.75","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 600 ÷ 8 = 75예요.","60은 600의 ⟨1/10⟩배라서 몫도 75의 ⟨1/10⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 60 ÷ 8 = 7.5예요."]},{"stem":"6 ÷ 5의 몫은 얼마인가요?","options":[{"t":"1.2","correct":true},{"t":"1.1","mis":"M6-1-u3-X08"},{"t":"12","mis":"M6-1-u3-X01"},{"t":"0.12","mis":"M6-1-u3-X02"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 60 ÷ 5 = 12예요.","6은 60의 ⟨1/10⟩배라서 몫도 12의 ⟨1/10⟩배예요.","자연수를 소수점 아래 0이 있는 수로 보고 0을 내려 계산해요 — 6 ÷ 5 = 1.2예요."]}]}}'::jsonb),
('g6_1_math_u3_review_d#13','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C6',2,'ox','auto','6 ÷ 5의 몫은 1.1이에요.',ARRAY['M6-1-u3-X08']::text[],true,'{"seq":13,"concept":"M6-1-u3-C6","difficulty":2,"kind":"ox","stem":"6 ÷ 5의 몫은 1.1이에요.","answer":"X","reason_options":[{"t":"나머지 1에 0을 내려 10 ÷ 5 = 2를 이어 계산하면 1.2이기 때문에","correct":true},{"t":"6 ÷ 5 = 1 … 1이라 나머지를 소수로 쓰기 때문에","mis":"M6-1-u3-X08"}],"mis":"M6-1-u3-X08","explanation":["자연수의 소수점은 자연수 바로 뒤에 있어요 — 6 = 6.0이에요.","나머지가 남으면 0을 내려 계산을 이어 가요.","몫을 분수로 쓴 뒤 분모를 10·100으로 고쳐 소수로 나타낼 수도 있어요."],"variant_rule":{"alt":[{"stem":"648 ÷ 2 = 324이면 6.48 ÷ 2 = 32.4예요.","answer":"X","reason_options":[{"t":"6.48은 648의 ⟨1/100⟩배라서 몫도 ⟨1/100⟩배인 3.24이기 때문에","correct":true},{"t":"나누어지는 수의 소수점을 한 칸만 옮기면 되기 때문에","mis":"M6-1-u3-X02"}],"explanation":["소수는 0.1이나 0.01이 몇 개인 수로 볼 수 있어요.","나누는 수가 같을 때 나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배가 돼요.","분수의 나눗셈으로 바꾸면 ÷ 자연수는 × 자연수분의 1이에요."]},{"stem":"5.6 ÷ 7의 몫은 8이에요.","answer":"X","reason_options":[{"t":"몫이 1보다 작아 일의 자리에 0을 써서 0.8이기 때문에","correct":true},{"t":"56 ÷ 7 = 8이니 몫도 8이기 때문에","mis":"M6-1-u3-X05"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫은 1보다 작아요.","이때 몫의 일의 자리에 0을 써요.","0은 자리를 지키는 숫자예요."]}]}}'::jsonb),
('g6_1_math_u3_review_d#14','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C3',2,'mc','auto','다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?',ARRAY['M6-1-u3-X12']::text[],true,'{"seq":14,"concept":"M6-1-u3-C3","difficulty":2,"kind":"mc","stem":"다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"4.15 ÷ 5","correct":true},{"t":"9.9 ÷ 9","mis":"M6-1-u3-X12"},{"t":"6.6 ÷ 6","mis":"M6-1-u3-X12"},{"t":"8.8 ÷ 4","mis":"M6-1-u3-X12"}],"explanation":["몫이 1보다 작으려면 나누어지는 수가 나누는 수보다 작아야 해요.","나누어지는 수와 나누는 수를 하나씩 견주어 봐요.","4.15 ÷ 5만 나누어지는 수가 더 작아요 — 몫은 0.83이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"7.29 ÷ 9","correct":true},{"t":"14.9 ÷ 5","mis":"M6-1-u3-X12"},{"t":"8.4 ÷ 8","mis":"M6-1-u3-X12"},{"t":"4.16 ÷ 4","mis":"M6-1-u3-X12"}],"explanation":["몫이 1보다 작으려면 나누어지는 수가 나누는 수보다 작아야 해요.","나누어지는 수와 나누는 수를 하나씩 견주어 봐요.","7.29 ÷ 9만 나누어지는 수가 더 작아요 — 몫은 0.81이에요."]},{"stem":"이번에는 다른 보기예요. 다음 가운데 몫이 1보다 작은 나눗셈은 어느 것인가요?","options":[{"t":"6.3 ÷ 7","correct":true},{"t":"9.6 ÷ 8","mis":"M6-1-u3-X12"},{"t":"5.5 ÷ 5","mis":"M6-1-u3-X12"},{"t":"12.6 ÷ 6","mis":"M6-1-u3-X12"}],"explanation":["몫이 1보다 작으려면 나누어지는 수가 나누는 수보다 작아야 해요.","나누어지는 수와 나누는 수를 하나씩 견주어 봐요.","6.3 ÷ 7만 나누어지는 수가 더 작아요 — 몫은 0.9예요."]}]}}'::jsonb),
('g6_1_math_u3_review_d#15','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C1',2,'mc','auto','리본 9.6 m를 세 명이 똑같이 나누어 가져요. 한 명이 가지는 리본은 몇 m인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X02','M6-1-u3-X10']::text[],true,'{"seq":15,"concept":"M6-1-u3-C1","difficulty":2,"kind":"mc","stem":"리본 9.6 m를 세 명이 똑같이 나누어 가져요. 한 명이 가지는 리본은 몇 m인가요?","options":[{"t":"3.2 m","correct":true},{"t":"32 m","mis":"M6-1-u3-X01"},{"t":"0.32 m","mis":"M6-1-u3-X02"},{"t":"28.8 m","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 96 ÷ 3 = 32예요.","9.6은 96의 ⟨1/10⟩배라서 몫도 32의 ⟨1/10⟩배예요.","9.6 ÷ 3 = 3.2예요."],"variant_rule":{"alt":[{"stem":"걷기 대회 코스는 모두 6.8 km예요. 반환점은 코스의 정확히 절반 지점에 있어요. 반환점까지는 몇 km인가요?","options":[{"t":"3.4 km","correct":true},{"t":"34 km","mis":"M6-1-u3-X01"},{"t":"0.34 km","mis":"M6-1-u3-X02"},{"t":"13.6 km","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 68 ÷ 2 = 34예요.","6.8은 68의 ⟨1/10⟩배라서 몫도 34의 ⟨1/10⟩배예요.","6.8 ÷ 2 = 3.4예요."]},{"stem":"쌀 84.88 kg을 자루 4개에 똑같이 나누어 담았어요. 자루 한 개에 담긴 쌀은 몇 kg인가요?","options":[{"t":"21.22 kg","correct":true},{"t":"212.2 kg","mis":"M6-1-u3-X01"},{"t":"2.122 kg","mis":"M6-1-u3-X02"},{"t":"339.52 kg","mis":"M6-1-u3-X10"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 8488 ÷ 4 = 2122예요.","84.88은 8488의 ⟨1/100⟩배라서 몫도 2122의 ⟨1/100⟩배예요.","84.88 ÷ 4 = 21.22예요."]}]}}'::jsonb),
('g6_1_math_u3_review_d#16','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C2',2,'sa','auto','넓이가 38.4 cm²이고 가로가 6 cm인 직사각형이 있어요. 이 직사각형의 세로는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M6-1-u3-C2","difficulty":2,"kind":"sa","stem":"넓이가 38.4 cm²이고 가로가 6 cm인 직사각형이 있어요. 이 직사각형의 세로는 몇 mm인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["직사각형의 넓이 = 가로 × 세로이니 세로 = 넓이 ÷ 가로요예요.","38.4 ÷ 6 = 6.4 (cm)예요.","1 cm는 10 mm라서 6.4 cm는 64 mm예요."],"mis":"M6-1-u3-X11","variant_rule":{"alt":[{"stem":"넓이가 45.6 cm²이고 가로가 8 cm인 직사각형이 있어요. 이 직사각형의 세로는 몇 mm인가요? 숫자로 쓰세요.","answer":["57"],"explanation":["직사각형의 넓이 = 가로 × 세로이니 세로 = 넓이 ÷ 가로요예요.","45.6 ÷ 8 = 5.7 (cm)예요.","1 cm는 10 mm라서 5.7 cm는 57 mm예요."]},{"stem":"넓이가 25.2 cm²이고 밑변이 4 cm인 평행사변형이 있어요. 이 평행사변형의 높이는 몇 mm인가요? 숫자로 쓰세요.","answer":["63"],"explanation":["평행사변형의 넓이 = 밑변 × 높이이니 높이 = 넓이 ÷ 밑변이에.","25.2 ÷ 4 = 6.3 (cm)예요.","1 cm는 10 mm라서 6.3 cm는 63 mm예요."]}]}}'::jsonb),
('g6_1_math_u3_review_d#17','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C5',3,'mc','auto','친구가 12.3 ÷ 6의 몫을 2.5라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X06','M6-1-u3-X05']::text[],true,'{"seq":17,"concept":"M6-1-u3-C5","difficulty":3,"kind":"mc","stem":"친구가 12.3 ÷ 6의 몫을 2.5라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"내린 수가 나누는 수보다 작을 때 몫에 0을 쓰지 않아서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1230 ÷ 6 = 205예요.","내린 수가 6보다 작으면 몫에 0을 쓰고 하나 더 내려야 해요.","바른 몫은 2.05이고 2.5는 다른 수예요."],"variant_rule":{"alt":[{"stem":"친구가 18.1 ÷ 2의 몫을 9.5라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"내린 수가 나누는 수보다 작을 때 몫에 0을 쓰지 않아서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1810 ÷ 2 = 905예요.","내린 수가 2보다 작으면 몫에 0을 쓰고 하나 더 내려야 해요.","바른 몫은 9.05이고 9.5는 다른 수예요."]},{"stem":"친구가 20.2 ÷ 5의 몫을 4.4라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"내린 수가 나누는 수보다 작을 때 몫에 0을 쓰지 않아서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2020 ÷ 5 = 404예요.","내린 수가 5보다 작으면 몫에 0을 쓰고 하나 더 내려야 해요.","바른 몫은 4.04이고 4.4는 다른 수예요."]}]}}'::jsonb),
('g6_1_math_u3_review_d#18','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C3',3,'mc','auto','친구가 2.38 ÷ 7의 몫을 34라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X13','M6-1-u3-X06']::text[],true,'{"seq":18,"concept":"M6-1-u3-C3","difficulty":3,"kind":"mc","stem":"친구가 2.38 ÷ 7의 몫을 34라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"몫이 1보다 작은데 일의 자리 0과 소수점을 쓰지 않아서","correct":true},{"t":"나누는 수를 잘못 써서","mis":"M6-1-u3-X13"},{"t":"곱셈을 잘못해서","mis":"M6-1-u3-X13"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"}],"explanation":["2.38은 7보다 작아 몫이 1보다 작아요.","자연수의 나눗셈으로 바꾸어 봐요 — 238 ÷ 7 = 34예요.","일의 자리에 0을 쓰고 소수점을 찍어 0.34예요."],"variant_rule":{"alt":[{"stem":"친구가 3.2 ÷ 4의 몫을 8이라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"몫이 1보다 작은데 일의 자리 0과 소수점을 쓰지 않아서","correct":true},{"t":"나누는 수를 잘못 써서","mis":"M6-1-u3-X13"},{"t":"곱셈을 잘못해서","mis":"M6-1-u3-X13"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"}],"explanation":["3.2는 4보다 작아 몫이 1보다 작아요.","자연수의 나눗셈으로 바꾸어 봐요 — 32 ÷ 4 = 8이에요.","일의 자리에 0을 쓰고 소수점을 찍어 0.8이에요."]},{"stem":"친구가 4.15 ÷ 5의 몫을 83이라고 썼어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"몫이 1보다 작은데 일의 자리 0과 소수점을 쓰지 않아서","correct":true},{"t":"나누는 수를 잘못 써서","mis":"M6-1-u3-X13"},{"t":"곱셈을 잘못해서","mis":"M6-1-u3-X13"},{"t":"0을 내려 계산하지 않아서","mis":"M6-1-u3-X06"}],"explanation":["4.15는 5보다 작아 몫이 1보다 작아요.","자연수의 나눗셈으로 바꾸어 봐요 — 415 ÷ 5 = 83이에요.","일의 자리에 0을 쓰고 소수점을 찍어 0.83이에요."]}]}}'::jsonb),
('g6_1_math_u3_review_d#19','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C6',3,'mc','auto','친구가 17 ÷ 4 = 4 … 1을 보고 몫을 4.1로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u3-X01','M6-1-u3-X09','M6-1-u3-X05']::text[],true,'{"seq":19,"concept":"M6-1-u3-C6","difficulty":3,"kind":"mc","stem":"친구가 17 ÷ 4 = 4 … 1을 보고 몫을 4.1로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지 1을 그대로 소수 부분으로 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"나누는 수와 나누어지는 수를 바꾸어서","mis":"M6-1-u3-X09"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["나머지 1은 아직 나누지 않은 양이라 몫의 소수 부분이 아니에요.","17을 17.0으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 4.25예요."],"variant_rule":{"alt":[{"stem":"친구가 6 ÷ 5 = 1 … 1을 보고 몫을 1.1로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지 1을 그대로 소수 부분으로 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"나누는 수와 나누어지는 수를 바꾸어서","mis":"M6-1-u3-X09"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["나머지 1은 아직 나누지 않은 양이라 몫의 소수 부분이 아니에요.","6을 6.0으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 1.2예요."]},{"stem":"친구가 9 ÷ 6 = 1 … 3을 보고 몫을 1.3으로 나타냈어요. 잘못된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나머지 3을 그대로 소수 부분으로 써서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-1-u3-X01"},{"t":"나누는 수와 나누어지는 수를 바꾸어서","mis":"M6-1-u3-X09"},{"t":"일의 자리에 0을 쓰지 않아서","mis":"M6-1-u3-X05"}],"explanation":["나머지 3은 아직 나누지 않은 양이라 몫의 소수 부분이 아니에요.","9를 9.0으로 보고 0을 내려 계산을 이어 가요.","바른 몫은 1.5예요."]}]}}'::jsonb),
('g6_1_math_u3_review_d#20','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C7',3,'mc','auto','가 상자 3통 18.3 kg · 라 상자 6통 25.2 kg · 마 상자 5통 14.5 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?',ARRAY['M6-1-u3-X12','M6-1-u3-X14']::text[],true,'{"seq":20,"concept":"M6-1-u3-C7","difficulty":3,"kind":"mc","stem":"가 상자 3통 18.3 kg · 라 상자 6통 25.2 kg · 마 상자 5통 14.5 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?","options":[{"t":"가 상자","correct":true},{"t":"라 상자","mis":"M6-1-u3-X12"},{"t":"마 상자","mis":"M6-1-u3-X14"},{"t":"모두 같아요","mis":"M6-1-u3-X12"}],"explanation":["먼저 어림해요 — 18 ÷ 3 = 6, 24 ÷ 6 = 4, 15 ÷ 5 = 3이에요.","계산으로 확인하면 가 6.1 kg, 라 4.2 kg, 마 2.9 kg이에요.","수박 한 통이 가장 무거운 것은 가 상자예요."],"variant_rule":{"alt":[{"stem":"가 상자 3통 18.3 kg · 나 상자 4통 19.8 kg · 다 상자 5통 20.2 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?","options":[{"t":"가 상자","correct":true},{"t":"나 상자","mis":"M6-1-u3-X12"},{"t":"다 상자","mis":"M6-1-u3-X14"},{"t":"모두 같아요","mis":"M6-1-u3-X12"}],"explanation":["먼저 어림해요 — 18 ÷ 3 = 6, 20 ÷ 4 = 5, 20 ÷ 5 = 4예요.","계산으로 확인하면 가 6.1 kg, 나 4.95 kg, 다 4.04 kg이에요.","수박 한 통이 가장 무거운 것은 가 상자예요."]},{"stem":"라 상자 6통 25.2 kg · 마 상자 5통 14.5 kg · 바 상자 4통 22.4 kg — 수박 한 통이 가장 무거운 상자는 어느 것인가요?","options":[{"t":"바 상자","correct":true},{"t":"라 상자","mis":"M6-1-u3-X12"},{"t":"마 상자","mis":"M6-1-u3-X14"},{"t":"모두 같아요","mis":"M6-1-u3-X12"}],"explanation":["먼저 어림해요 — 24 ÷ 6 = 4, 15 ÷ 5 = 3, 24 ÷ 4 = 6이에요.","계산으로 확인하면 라 4.2 kg, 마 2.9 kg, 바 5.6 kg이에요.","수박 한 통이 가장 무거운 것은 바 상자예요."]}]}}'::jsonb),
('g6_1_math_u3_review_d#21','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C5',3,'error','auto','18.1 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u3-X07','M6-1-u3-X14']::text[],true,'{"seq":21,"concept":"M6-1-u3-C5","difficulty":3,"kind":"error","stem":"18.1 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「몫은 9.5야.」","correct":true,"mis_target":"M6-1-u3-X07"},{"t":"라온 — 「몫은 9보다 조금 커.」","mis":"M6-1-u3-X14"},{"t":"예준 — 「몫의 소수 첫째 자리에 0이 들어가.」","mis":"M6-1-u3-X14"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1810 ÷ 2 = 905예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 18.1 ÷ 2 = 9.05예요.","여울은 몫 가운데 0을 빠뜨렸어요."],"variant_rule":{"alt":[{"stem":"585 ÷ 5 = 117을 이용해 58.5 ÷ 5를 계산하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「나누어지는 수가 작아졌으니 몫은 117의 10배야.」","correct":true,"mis_target":"M6-1-u3-X01"},{"t":"이현 — 「58.5는 585의 ⟨1/10⟩배야.」","mis":"M6-1-u3-X14"},{"t":"서아 — 「몫은 11.7이야.」","mis":"M6-1-u3-X14"}],"explanation":["나누는 수 5는 그대로예요.","나누어지는 수가 ⟨1/10⟩배가 되면 몫도 ⟨1/10⟩배예요.","준희는 몫이 커진다고 거꾸로 말했어요."]},{"stem":"49.2 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「몫은 123이야.」","correct":true,"mis_target":"M6-1-u3-X01"},{"t":"수아 — 「492 ÷ 4를 계산한 몫의 ⟨1/10⟩배야.」","mis":"M6-1-u3-X14"},{"t":"도윤 — 「몫의 소수점은 49.2의 소수점 위에 찍어.」","mis":"M6-1-u3-X14"}],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 492 ÷ 4 = 123이에요.","49.2는 492의 ⟨1/10⟩배라서 몫도 123의 ⟨1/10⟩배예요.","서호는 몫의 소수점을 한 자리 뒤에 찍었어요 — 바른 몫은 12.3이에요."]}]}}'::jsonb),
('g6_1_math_u3_review_d#22','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C5',3,'sa','auto','2.0□가 16.4 ÷ 8의 몫보다 작아요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M6-1-u3-C5","difficulty":3,"kind":"sa","stem":"2.0□가 16.4 ÷ 8의 몫보다 작아요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 1640 ÷ 8 = 205예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 16.4 ÷ 8 = 2.05예요.","2.0□ < 2.05 — □는 1부터 4까지, 4개예요."],"mis":"M6-1-u3-X07","variant_rule":{"alt":[{"stem":"6.0□가 48.4 ÷ 8의 몫보다 커요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 4840 ÷ 8 = 605예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 48.4 ÷ 8 = 6.05예요.","6.0□ > 6.05 — □는 6부터 9까지, 4개예요."]},{"stem":"4.0□가 24.3 ÷ 6의 몫보다 커요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수의 나눗셈으로 바꾸어 봐요 — 2430 ÷ 6 = 405예요.","내린 수가 나누는 수보다 작으면 몫에 0을 쓰고 하나 더 내려요 — 24.3 ÷ 6 = 4.05예요.","4.0□ > 4.05 — □는 6부터 9까지, 4개예요."]}]}}'::jsonb),
('g6_1_math_u3_review_d#23','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C7',4,'mc','auto','아 상자는 수박 6통이 30.6 kg, 마 상자는 수박 5통이 14.5 kg이에요. 마 상자의 수박 한 통은 아 상자의 수박 한 통보다 몇 kg 가벼운가요?',ARRAY['M6-1-u3-X14','M6-1-u3-X01','M6-1-u3-X02']::text[],true,'{"seq":23,"concept":"M6-1-u3-C7","difficulty":4,"kind":"mc","stem":"아 상자는 수박 6통이 30.6 kg, 마 상자는 수박 5통이 14.5 kg이에요. 마 상자의 수박 한 통은 아 상자의 수박 한 통보다 몇 kg 가벼운가요?","options":[{"t":"2.2 kg","correct":true},{"t":"8 kg","mis":"M6-1-u3-X14"},{"t":"22 kg","mis":"M6-1-u3-X01"},{"t":"0.22 kg","mis":"M6-1-u3-X02"}],"explanation":["아 상자 한 통은 30.6 ÷ 6 = 5.1 (kg)이에요.","마 상자 한 통은 14.5 ÷ 5 = 2.9 (kg)이에요.","5.1 − 2.9 = 2.2 (kg) 가벼워요."],"variant_rule":{"alt":[{"stem":"가 상자는 수박 3통이 18.3 kg, 라 상자는 수박 6통이 25.2 kg이에요. 라 상자의 수박 한 통은 가 상자의 수박 한 통보다 몇 kg 가벼운가요?","options":[{"t":"1.9 kg","correct":true},{"t":"10.3 kg","mis":"M6-1-u3-X14"},{"t":"19 kg","mis":"M6-1-u3-X01"},{"t":"0.19 kg","mis":"M6-1-u3-X02"}],"explanation":["가 상자 한 통은 18.3 ÷ 3 = 6.1 (kg)이에요.","라 상자 한 통은 25.2 ÷ 6 = 4.2 (kg)이에요.","6.1 − 4.2 = 1.9 (kg) 가벼워요."]},{"stem":"가 상자는 수박 3통이 18.3 kg, 나 상자는 수박 4통이 19.8 kg이에요. 나 상자의 수박 한 통은 가 상자의 수박 한 통보다 몇 kg 가벼운가요?","options":[{"t":"1.15 kg","correct":true},{"t":"11.05 kg","mis":"M6-1-u3-X14"},{"t":"11.5 kg","mis":"M6-1-u3-X01"},{"t":"0.115 kg","mis":"M6-1-u3-X02"}],"explanation":["가 상자 한 통은 18.3 ÷ 3 = 6.1 (kg)이에요.","나 상자 한 통은 19.8 ÷ 4 = 4.95 (kg)이에요.","6.1 − 4.95 = 1.15 (kg) 가벼워요."]}]}}'::jsonb),
('g6_1_math_u3_review_d#24','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C5',4,'essay','teacher','강변을 자전거로 같은 빠르기로 18.1 km를 달리는 데 2시간이 걸렸어요. 한 시간 동안 달린 거리를 구하고, 친구가 쓴 9.5 km가 왜 틀렸는지 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u3-C5","difficulty":4,"kind":"essay","stem":"강변을 자전거로 같은 빠르기로 18.1 km를 달리는 데 2시간이 걸렸어요. 한 시간 동안 달린 거리를 구하고, 친구가 쓴 9.5 km가 왜 틀렸는지 설명해 보세요.","answer_guide":{"answer":"예: 18.1 ÷ 2를 계산한다. 18을 2로 나누면 9이고 1을 내렸지만 1은 2보다 작으므로 몫에 0을 쓰고 수를 하나 더 내려 10 ÷ 2 = 5로 계산한다. 그래서 몫은 9.05이고 한 시간에 9.05 km를 달렸다. 9.5는 몫 가운데 0을 빠뜨려 전혀 다른 수가 되었다.","scoring_points":["몫에 0을 쓰고 하나 더 내렸는가","9.05 km를 구했는가","9.5는 0을 빠뜨린 것이라고 설명했는가"]},"explanation":["1을 내려도 2보다 작아 몫에 0을 써요.","18.1 ÷ 2 = 9.05 — 9.05 km예요.","9.5는 0을 빠뜨렸어요."]}'::jsonb),
('g6_1_math_u3_review_d#25','math',6,1,'u3','','g6_1_math_u3_review_d','unit_review','M6-1-u3-C4',4,'essay','teacher','넓이가 4.6 m²인 벽을 칠하는 데 페인트 4통을 똑같이 썼어요. 4.6 ÷ 4를 계산하다가 2가 남았을 때 어떻게 해야 하는지 쓰고, 페인트 한 통으로 칠한 넓이를 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u3-C4","difficulty":4,"kind":"essay","stem":"넓이가 4.6 m²인 벽을 칠하는 데 페인트 4통을 똑같이 썼어요. 4.6 ÷ 4를 계산하다가 2가 남았을 때 어떻게 해야 하는지 쓰고, 페인트 한 통으로 칠한 넓이를 구해 보세요.","answer_guide":{"answer":"예: 4.6은 4.60과 같은 수이므로 소수점 아래에 0을 하나 내려 계산을 이어 간다. 남은 2에 0을 내리면 20 ÷ 4 = 5로 나누어떨어진다. 그래서 4.6 ÷ 4 = 1.15이고 페인트 한 통으로 1.15 m²를 칠했다.","scoring_points":["4.6 = 4.60이라는 까닭을 썼는가","0을 내려 계산을 이어 갔는가","1.15 m²를 구했는가"]},"explanation":["4.6 = 4.60이에요.","0을 내려 20 ÷ 4 = 5를 이어 계산해요.","한 통으로 1.15 m²예요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('M6-1-u4-C1','math',6,1,'u4',2,'두 양을 차와 배로 비교하기 — 뺄셈으로 비교하면 차, 나눗셈으로 비교하면 몇 배인지 알 수 있고, 두 양이 같은 배로 늘어나면 차는 변하지만 배로 비교한 관계는 변하지 않음을 알기',ARRAY['6수04-01']::text[],1),
('M6-1-u4-C2','math',6,1,'u4',2,'비 알기 — 두 양의 변하지 않는 관계를 기호 ：을 써서 2：10처럼 나타내고, 「○에 대한」 쪽이 기준량(후항), 다른 쪽이 비교하는 양(전항)임을 알며, 순서를 바꾸면 다른 비가 됨을 알기',ARRAY['6수04-01']::text[],2),
('M6-1-u4-C3','math',6,1,'u4',3,'비율 알기 — 기준량에 대한 비교하는 양의 크기를 (비교하는 양) ÷ (기준량)으로 구해 분수나 소수로 나타내고, 비율이 1보다 클 수도 있으며 기준량이 달라도 관계가 같으면 비율이 같음을 알기',ARRAY['6수04-02']::text[],3),
('M6-1-u4-C4','math',6,1,'u4',4,'비율이 사용되는 경우 — 경기 결과(전체 경기 수에 대한 이긴 경기 수), 걸린 시간에 대한 이동 거리, 넓이에 대한 인구, 지도의 거리처럼 생활 속 비율을 구하고, 기준이 다른 것끼리는 수가 아니라 비율로 비교하기',ARRAY['6수04-02']::text[],4),
('M6-1-u4-C5','math',6,1,'u4',5,'백분율 알기 — 기준량을 100으로 할 때의 비율을 백분율이라 하고 기호 %로 나타내며, 기준량이 100인 비율로 바꾸거나 비율에 100을 곱해 백분율로 나타내고, 백분율을 분수·소수로도 바꾸기',ARRAY['6수04-02']::text[],5),
('M6-1-u4-C6','math',6,1,'u4',6,'백분율이 사용되는 경우 — 득표율, 이자율, 할인율(원래 가격에 대한 할인 금액), 설탕물의 진하기(설탕물 양에 대한 설탕 양)를 백분율로 구하고, 금액이나 양이 아니라 백분율로 비교하기',ARRAY['6수04-02']::text[],6),
('M6-1-u4-C7','math',6,1,'u4',7,'백분율로 문제 해결하기 — 이해·계획·해결·검토 네 단계로, 전체를 100칸으로 보고 한 칸(1 %)의 크기부터 구해 전체의 몇 %인 양을 구하며, 조건이 바뀌면 기준량이 무엇인지 다시 확인하고 구한 답을 비율로 만들어 검토하기',ARRAY['6수04-02']::text[],7)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('M6-1-u4-X01','math',6,'u4',ARRAY['M6-1-u4-C2','M6-1-u4-C3','M6-1-u4-C4']::text[],'기준량과 비교하는 양을 바꾸어 비를 쓴다(「바닷물 양에 대한 소금 양의 비」를 150：6으로)','「○에 대한」 쪽이 기준량, 뒤에 써요'),
('M6-1-u4-X02','math',6,'u4',ARRAY['M6-1-u4-C2']::text[],'비의 순서를 바꾸어도 같은 비라고 본다(3：4와 4：3을 같다고)','기준량이 바뀌면 다른 비'),
('M6-1-u4-X03','math',6,'u4',ARRAY['M6-1-u4-C1','M6-1-u4-C2','M6-1-u4-C4']::text[],'몇 배인지 비교해야 할 때 뺄셈으로 차를 구하거나, 몇 배로 늘려야 할 때 같은 수를 더한다','「몇 배」는 나눗셈'),
('M6-1-u4-X04','math',6,'u4',ARRAY['M6-1-u4-C1']::text[],'두 양이 같은 배로 늘 때 차도 그대로라고 보거나, 배 관계가 변한다고 본다','늘어나도 그대로인 것은 배'),
('M6-1-u4-X05','math',6,'u4',ARRAY['M6-1-u4-C3','M6-1-u4-C4','M6-1-u4-C6']::text[],'비율을 (기준량) ÷ (비교하는 양)으로 거꾸로 나눈다(9：50의 비율을 50 ÷ 9로)','비교하는 양 ÷ 기준량'),
('M6-1-u4-X06','math',6,'u4',ARRAY['M6-1-u4-C3']::text[],'비율은 언제나 1보다 작다고 본다(12：5의 비율 2.4를 틀렸다고)','비교하는 양이 더 크면 비율은 1보다 커요'),
('M6-1-u4-X07','math',6,'u4',ARRAY['M6-1-u4-C2','M6-1-u4-C3','M6-1-u4-C4','M6-1-u4-C6']::text[],'전체에 대한 비에서 전체 대신 다른 한 부분을 기준량으로 쓰거나, 한 부분 대신 전체를 쓴다(남 10·여 13에서 전체에 대한 여학생 비를 13：10으로)','전체 = 부분 + 부분'),
('M6-1-u4-X08','math',6,'u4',ARRAY['M6-1-u4-C5','M6-1-u4-C6','M6-1-u4-C7']::text[],'비율을 백분율로 바꿀 때 100이 아닌 10·1000을 곱하거나 곱하지 않는다(0.07을 70 %·0.7 %로)','비율 × 100에 % 붙이기'),
('M6-1-u4-X09','math',6,'u4',ARRAY['M6-1-u4-C5','M6-1-u4-C6']::text[],'분수를 백분율로 바꿀 때 분자를 그대로 %로 쓰는 등 기준량을 100으로 맞추지 않는다(⟨16/25⟩를 16 %로)','분모를 100으로 고쳐요'),
('M6-1-u4-X10','math',6,'u4',ARRAY['M6-1-u4-C6','M6-1-u4-C7']::text[],'할인율을 구할 때 할인 금액 대신 할인된 가격을 쓴다','할인 금액 = 원래 가격 − 할인된 가격'),
('M6-1-u4-X11','math',6,'u4',ARRAY['M6-1-u4-C3','M6-1-u4-C4','M6-1-u4-C5','M6-1-u4-C6','M6-1-u4-C7']::text[],'기준량이 다른데 수·금액·양의 크기만으로 비교한다(넣은 횟수·인구·할인 금액이 크면 더 잘했다·빽빽하다·싸다고)','기준이 다르면 비율로'),
('M6-1-u4-X12','math',6,'u4',ARRAY['M6-1-u4-C6']::text[],'설탕물의 진하기를 구할 때 기준량을 설탕물 대신 물의 양으로 쓴다','설탕물 = 물 + 설탕'),
('M6-1-u4-X13','math',6,'u4',ARRAY['M6-1-u4-C7']::text[],'전체의 몇 %를 구할 때 %의 수를 그대로 답하거나, 전체를 %의 수로 나누거나, 한 칸(1 %)만 구하고 멈춘다','한 칸 × 칸 수'),
('M6-1-u4-X14','math',6,'u4',ARRAY['M6-1-u4-C7']::text[],'조건이 바뀌어 기준량이 달라졌는데 처음 전체를 그대로 기준량으로 쓴다(신재생 에너지의 48 %를 전체 발전량의 48 %로)','「무엇의」 몇 %인지'),
('M6-1-u4-X15','math',6,'u4',ARRAY['M6-1-u4-C1','M6-1-u4-C2','M6-1-u4-C3','M6-1-u4-C4','M6-1-u4-C5','M6-1-u4-C6','M6-1-u4-C7']::text[],'분수·소수 셈(약분·나눗셈·자릿값)을 잘못 계산한다','곱셈으로 거꾸로 확인해요'),
('M6-1-u4-X16','math',6,'u4',ARRAY['M6-1-u4-C1','M6-1-u4-C2','M6-1-u4-C3','M6-1-u4-C4','M6-1-u4-C5','M6-1-u4-C6','M6-1-u4-C7']::text[],'묻는 말을 놓친다 — 이긴 경기↔진 경기, 할인 금액↔할인된 가격, 쓴 양↔남은 양, 가장 큰↔작은','물음의 「무엇을·가장」에 동그라미')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g6_1_math_u4_L02_basic#1','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C1',1,'sa','auto','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 뺄셈으로 비교하면 물은 매실 원액보다 몇 컵 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u4-C1","difficulty":1,"kind":"sa","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 뺄셈으로 비교하면 물은 매실 원액보다 몇 컵 더 많은가요? 숫자로 쓰세요.","answer":["3"],"explanation":["뺄셈으로 비교하면 두 양의 차를 알 수 있어요.","4 − 1 = 3이에요.","물은 매실 원액보다 3컵 더 많아요."],"mis":"M6-1-u4-X16","variant_rule":{"alt":[{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 뺄셈으로 비교하면 노란 구슬은 파란 구슬보다 몇 개 더 많은가요? 숫자로 쓰세요.","answer":["8"],"explanation":["뺄셈으로 비교하면 두 양의 차를 알 수 있어요.","10 − 2 = 8이에요.","노란 구슬은 파란 구슬보다 8개 더 많아요."]},{"stem":"꽃다발 한 개에는 안개꽃 12송이와 장미 3송이가 들어가요. 뺄셈으로 비교하면 안개꽃은 장미보다 몇 송이 더 많은가요? 숫자로 쓰세요.","answer":["9"],"explanation":["뺄셈으로 비교하면 두 양의 차를 알 수 있어요.","12 − 3 = 9예요.","안개꽃은 장미보다 9송이 더 많아요."]}]}}'::jsonb),
('g6_1_math_u4_L02_basic#2','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C1',1,'sa','auto','팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 나눗셈으로 비교하면 노란 구슬은 파란 구슬의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u4-C1","difficulty":1,"kind":"sa","stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 나눗셈으로 비교하면 노란 구슬은 파란 구슬의 몇 배인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","10 ÷ 2 = 5예요.","노란 구슬은 파란 구슬의 5배예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 나눗셈으로 비교하면 물은 매실 원액의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","4 ÷ 1 = 4예요.","물은 매실 원액의 4배예요."]},{"stem":"하늘색 물감 한 접시에는 흰색 물감 8방울과 파란색 물감 2방울이 들어가요. 나눗셈으로 비교하면 흰색 물감은 파란색 물감의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","8 ÷ 2 = 4예요.","흰색 물감은 파란색 물감의 4배예요."]}]}}'::jsonb),
('g6_1_math_u4_L02_basic#3','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C2',1,'sa','auto','비 2：10에서 기준량은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u4-C2","difficulty":1,"kind":"sa","stem":"비 2：10에서 기준량은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","2：10에서 전항은 2, 후항은 10이에요.","그래서 기준량은 10이에요."],"mis":"M6-1-u4-X01","variant_rule":{"alt":[{"stem":"비 9：20에서 후항은 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","9：20에서 전항은 9, 후항은 20이에요.","그래서 후항은 20이에요."]},{"stem":"비 3：4에서 전항은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","3：4에서 전항은 3, 후항은 4예요.","그래서 전항은 3이에요."]}]}}'::jsonb),
('g6_1_math_u4_L02_basic#4','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C2',1,'mc','auto','바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 어느 것인가요?',ARRAY['M6-1-u4-X01','M6-1-u4-X03']::text[],true,'{"seq":4,"concept":"M6-1-u4-C2","difficulty":1,"kind":"mc","stem":"바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 어느 것인가요?","options":[{"t":"6：150","correct":true},{"t":"150：6","mis":"M6-1-u4-X01"},{"t":"6：144","mis":"M6-1-u4-X03"},{"t":"25：1","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 바닷물 양이에요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 6：150이에요."],"variant_rule":{"alt":[{"stem":"팔찌 하나에 파란 구슬 2개와 노란 구슬 10개를 꿰어요. 파란 구슬 수와 노란 구슬 수의 비는 어느 것인가요?","options":[{"t":"2：10","correct":true},{"t":"10：2","mis":"M6-1-u4-X01"},{"t":"2：8","mis":"M6-1-u4-X03"},{"t":"5：1","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 노란 구슬 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 2：10이에요."]},{"stem":"닭 2마리와 병아리 5마리가 있어요. 닭 수에 대한 병아리 수의 비는 어느 것인가요?","options":[{"t":"5：2","correct":true},{"t":"2：5","mis":"M6-1-u4-X01"},{"t":"5：7","mis":"M6-1-u4-X07"},{"t":"3：5","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 닭 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 5：2예요."]}]}}'::jsonb),
('g6_1_math_u4_L02_basic#5','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C1',2,'mc','auto','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 수를 늘려도 변하지 않는 비교는 어느 것인가요?',ARRAY['M6-1-u4-X04']::text[],true,'{"seq":5,"concept":"M6-1-u4-C1","difficulty":2,"kind":"mc","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 수를 늘려도 변하지 않는 비교는 어느 것인가요?","options":[{"t":"나눗셈으로 비교한 배","correct":true},{"t":"뺄셈으로 비교한 차","mis":"M6-1-u4-X04"},{"t":"물과 매실 원액을 더한 합","mis":"M6-1-u4-X04"},{"t":"매실 주스 수","mis":"M6-1-u4-X04"}],"explanation":["매실 주스 2병이면 물 8컵, 매실 원액 2컵이에요.","차는 3에서 6으로 변하지만 8 ÷ 2 = 4배는 그대로예요.","그래서 변하지 않는 비교는 나눗셈으로 비교한 배예요."],"variant_rule":{"alt":[{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 팔찌 수를 늘려도 변하지 않는 비교는 어느 것인가요?","options":[{"t":"나눗셈으로 비교한 배","correct":true},{"t":"뺄셈으로 비교한 차","mis":"M6-1-u4-X04"},{"t":"노란 구슬과 파란 구슬을 더한 합","mis":"M6-1-u4-X04"},{"t":"팔찌 수","mis":"M6-1-u4-X04"}],"explanation":["팔찌 2개이면 노란 구슬 20개, 파란 구슬 4개예요.","차는 8에서 16으로 변하지만 20 ÷ 4 = 5배는 그대로예요.","그래서 변하지 않는 비교는 나눗셈으로 비교한 배예요."]},{"stem":"하늘색 물감 한 접시에는 흰색 물감 8방울과 파란색 물감 2방울이 들어가요. 하늘색 물감 수를 늘려도 변하지 않는 비교는 어느 것인가요?","options":[{"t":"나눗셈으로 비교한 배","correct":true},{"t":"뺄셈으로 비교한 차","mis":"M6-1-u4-X04"},{"t":"흰색 물감과 파란색 물감을 더한 합","mis":"M6-1-u4-X04"},{"t":"하늘색 물감 수","mis":"M6-1-u4-X04"}],"explanation":["하늘색 물감 2접시이면 흰색 물감 16방울, 파란색 물감 4방울이에요.","차는 6에서 12로 변하지만 16 ÷ 4 = 4배는 그대로예요.","그래서 변하지 않는 비교는 나눗셈으로 비교한 배예요."]}]}}'::jsonb),
('g6_1_math_u4_L02_basic#6','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C1',2,'sa','auto','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 2병을 만들려면 물은 모두 몇 컵 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C1","difficulty":2,"kind":"sa","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 2병을 만들려면 물은 모두 몇 컵 필요한가요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 병에 물 4컵씩 들어가요.","2병이면 4 × 2 = 8이에요.","물은 모두 8컵 필요해요."],"mis":"M6-1-u4-X04","variant_rule":{"alt":[{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 팔찌 3개를 만들려면 노란 구슬은 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["30"],"explanation":["한 개에 노란 구슬 10개씩 들어가요.","3개이면 10 × 3 = 30이에요.","노란 구슬은 모두 30개 필요해요."]},{"stem":"꽃다발 한 개에는 안개꽃 12송이와 장미 3송이가 들어가요. 꽃다발 4개를 만들려면 안개꽃은 모두 몇 송이 필요한가요? 숫자로 쓰세요.","answer":["48"],"explanation":["한 개에 안개꽃 12송이씩 들어가요.","4개이면 12 × 4 = 48이에요.","안개꽃은 모두 48송이 필요해요."]}]}}'::jsonb),
('g6_1_math_u4_L02_basic#7','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C2',2,'ox','auto','비 2：10에서 2는 비교하는 양, 10은 기준량이에요.',ARRAY['M6-1-u4-X01']::text[],true,'{"seq":7,"concept":"M6-1-u4-C2","difficulty":2,"kind":"ox","stem":"비 2：10에서 2는 비교하는 양, 10은 기준량이에요.","answer":"O","reason_options":[{"t":"기호 ：의 뒤에 있는 수가 기준량이기 때문에","correct":true},{"t":"큰 수가 언제나 기준량이기 때문에","mis":"M6-1-u4-X01"}],"mis":"M6-1-u4-X01","explanation":["두 양의 변하지 않는 관계를 기호 ：로 나타낸 것이 비예요.","：의 앞은 비교하는 양(전항), 뒤는 기준량(후항)이에요.","「○에 대한」 쪽이 기준량이에요."],"variant_rule":{"alt":[{"stem":"「6에 대한 5의 비」는 6：5로 써요.","answer":"X","reason_options":[{"t":"「대한」 쪽 6이 기준량이라 5：6으로 쓰기 때문에","correct":true},{"t":"앞에 나온 수를 먼저 쓰기 때문에","mis":"M6-1-u4-X01"}],"explanation":["두 양의 변하지 않는 관계를 기호 ：로 나타낸 것이 비예요.","：의 앞은 비교하는 양(전항), 뒤는 기준량(후항)이에요.","「○에 대한」 쪽이 기준량이에요."]},{"stem":"「5 대 2」와 「2에 대한 5의 비」는 같은 비예요.","answer":"O","reason_options":[{"t":"둘 다 기준량이 2인 5：2이기 때문에","correct":true},{"t":"두 말에 같은 수가 들어 있기 때문에","mis":"M6-1-u4-X01"}],"explanation":["두 양의 변하지 않는 관계를 기호 ：로 나타낸 것이 비예요.","：의 앞은 비교하는 양(전항), 뒤는 기준량(후항)이에요.","「○에 대한」 쪽이 기준량이에요."]}]}}'::jsonb),
('g6_1_math_u4_L02_basic#8','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C2',2,'sa','auto','치즈 4장과 달걀부침 3개로 샌드위치를 만들었어요. 치즈 수에 대한 달걀부침 수의 비에서 기준량은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u4-C2","difficulty":2,"kind":"sa","stem":"치즈 4장과 달걀부침 3개로 샌드위치를 만들었어요. 치즈 수에 대한 달걀부침 수의 비에서 기준량은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["「치즈 수에 대한」이니 기준량은 치즈 수예요.","비는 3：4예요.","답은 4예요."],"mis":"M6-1-u4-X01","variant_rule":{"alt":[{"stem":"동전을 20번 던져 숫자 면이 9번 나왔어요. 동전을 던진 횟수에 대한 숫자 면이 나온 횟수의 비에서 기준량은 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["「던진 횟수에 대한」이니 기준량은 던진 횟수예요.","비는 9：20이에요.","답은 20이에요."]},{"stem":"꽃밭에 튤립 8송이와 장미 15송이가 있어요. 장미 수에 대한 튤립 수의 비에서 비교하는 양은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["「장미 수에 대한」이니 기준량은 장미 수 15예요.","비교하는 양은 튤립 수라 비는 8：15예요.","답은 8이에요."]}]}}'::jsonb),
('g6_1_math_u4_L02_basic#9','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C2',2,'mc','auto','3：4와 4：3에 대한 설명으로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u4-X02']::text[],true,'{"seq":9,"concept":"M6-1-u4-C2","difficulty":2,"kind":"mc","stem":"3：4와 4：3에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"기준량이 달라 서로 다른 비예요","correct":true},{"t":"같은 비예요","mis":"M6-1-u4-X02"},{"t":"두 수의 합이 같으니 같은 비예요","mis":"M6-1-u4-X02"},{"t":"순서만 다를 뿐 뜻이 같아요","mis":"M6-1-u4-X02"}],"explanation":["3：4의 기준량은 4이고 4：3의 기준량은 3이에요.","기준량이 다르면 다른 비예요.","비의 순서를 바꾸면 안 돼요."],"variant_rule":{"alt":[{"stem":"2：5와 5：2에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"기준량이 달라 서로 다른 비예요","correct":true},{"t":"같은 비예요","mis":"M6-1-u4-X02"},{"t":"두 수의 합이 같으니 같은 비예요","mis":"M6-1-u4-X02"},{"t":"순서만 다를 뿐 뜻이 같아요","mis":"M6-1-u4-X02"}],"explanation":["2：5의 기준량은 5이고 5：2의 기준량은 2예요.","기준량이 다르면 다른 비예요.","비의 순서를 바꾸면 안 돼요."]},{"stem":"7：3과 3：7에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"기준량이 달라 서로 다른 비예요","correct":true},{"t":"같은 비예요","mis":"M6-1-u4-X02"},{"t":"두 수의 합이 같으니 같은 비예요","mis":"M6-1-u4-X02"},{"t":"순서만 다를 뿐 뜻이 같아요","mis":"M6-1-u4-X02"}],"explanation":["7：3의 기준량은 3이고 3：7의 기준량은 7이에요.","기준량이 다르면 다른 비예요.","비의 순서를 바꾸면 안 돼요."]}]}}'::jsonb),
('g6_1_math_u4_L02_basic#10','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C1',3,'sa','auto','가로 5 cm, 세로 2 cm인 직사각형을 모양 그대로 키웠더니 세로가 6 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u4-C1","difficulty":3,"kind":"sa","stem":"가로 5 cm, 세로 2 cm인 직사각형을 모양 그대로 키웠더니 세로가 6 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 6 ÷ 2 = 3배가 되었어요.","가로도 5 × 3 = 15 (cm)예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"가로 4 cm, 세로 3 cm인 직사각형을 모양 그대로 키웠더니 세로가 9 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 9 ÷ 3 = 3배가 되었어요.","가로도 4 × 3 = 12 (cm)예요."]},{"stem":"가로 6 cm, 세로 4 cm인 직사각형을 모양 그대로 키웠더니 세로가 10 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 10 ÷ 4 = 2.5배가 되었어요.","가로도 6 × 2.5 = 15 (cm)예요."]}]}}'::jsonb),
('g6_1_math_u4_L02_challenge#1','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C1',2,'sa','auto','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 2병을 만들 때 물과 매실 원액의 차는 몇 컵인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u4-C1","difficulty":2,"kind":"sa","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 2병을 만들 때 물과 매실 원액의 차는 몇 컵인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["2병이면 물 8컵, 매실 원액 2컵이에요.","8 − 2 = 6이에요.","한 병일 때의 차 3과 달리 차는 6컵으로 변했어요."],"mis":"M6-1-u4-X04","variant_rule":{"alt":[{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 팔찌 3개를 만들 때 노란 구슬과 파란 구슬의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["3개이면 노란 구슬 30개, 파란 구슬 6개예요.","30 − 6 = 24예요.","한 개일 때의 차 8과 달리 차는 24개로 변했어요."]},{"stem":"하늘색 물감 한 접시에는 흰색 물감 8방울과 파란색 물감 2방울이 들어가요. 하늘색 물감 4접시를 만들 때 흰색 물감과 파란색 물감의 차는 몇 방울인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["4접시이면 흰색 물감 32방울, 파란색 물감 8방울이에요.","32 − 8 = 24예요.","한 접시일 때의 차 6과 달리 차는 24방울로 변했어요."]}]}}'::jsonb),
('g6_1_math_u4_L02_challenge#2','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C2',2,'mc','auto','비 3：5를 읽은 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M6-1-u4-X16','M6-1-u4-X01']::text[],true,'{"seq":2,"concept":"M6-1-u4-C2","difficulty":2,"kind":"mc","stem":"비 3：5를 읽은 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"3에 대한 5의 비","correct":true},{"t":"3 대 5","mis":"M6-1-u4-X16"},{"t":"5에 대한 3의 비","mis":"M6-1-u4-X01"},{"t":"3의 5에 대한 비","mis":"M6-1-u4-X01"}],"explanation":["3：5는 「3 대 5」라고 읽어요.","기준량이 5니 「5에 대한 3의 비」, 「3의 5에 대한 비」라고도 읽어요.","「3에 대한 5의 비」는 기준량이 3인 5：3이에요."],"variant_rule":{"alt":[{"stem":"비 4：7을 읽은 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"4에 대한 7의 비","correct":true},{"t":"4 대 7","mis":"M6-1-u4-X16"},{"t":"7에 대한 4의 비","mis":"M6-1-u4-X01"},{"t":"4의 7에 대한 비","mis":"M6-1-u4-X01"}],"explanation":["4：7은 「4 대 7」이라고 읽어요.","기준량이 7이니 「7에 대한 4의 비」, 「4의 7에 대한 비」라고도 읽어요.","「4에 대한 7의 비」는 기준량이 4인 7：4예요."]},{"stem":"비 2：9를 읽은 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"2에 대한 9의 비","correct":true},{"t":"2 대 9","mis":"M6-1-u4-X16"},{"t":"9에 대한 2의 비","mis":"M6-1-u4-X01"},{"t":"2의 9에 대한 비","mis":"M6-1-u4-X01"}],"explanation":["2：9는 「2 대 9」라고 읽어요.","기준량이 9니 「9에 대한 2의 비」, 「2의 9에 대한 비」라고도 읽어요.","「2에 대한 9의 비」는 기준량이 2인 9：2예요."]}]}}'::jsonb),
('g6_1_math_u4_L02_challenge#3','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C1',3,'error','auto','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 2병을 만드는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X04','M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C1","difficulty":3,"kind":"error","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 2병을 만드는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「2병을 만들어도 물은 매실 원액보다 3컵 더 많아.」","correct":true,"mis_target":"M6-1-u4-X04"},{"t":"이현 — 「물은 8컵 필요해.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「물은 언제나 매실 원액의 4배야.」","mis":"M6-1-u4-X16"}],"explanation":["2병이면 물 8컵, 매실 원액 2컵이에요.","차는 8 − 2 = 6으로 변해요.","준희는 차가 그대로라고 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 팔찌 3개를 만드는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「3개를 만들어도 노란 구슬은 파란 구슬보다 8개 더 많아.」","correct":true,"mis_target":"M6-1-u4-X04"},{"t":"수아 — 「노란 구슬은 30개 필요해.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「노란 구슬은 언제나 파란 구슬의 5배야.」","mis":"M6-1-u4-X16"}],"explanation":["3개이면 노란 구슬 30개, 파란 구슬 6개예요.","차는 30 − 6 = 24로 변해요.","서호는 차가 그대로라고 잘못 말했어요."]},{"stem":"꽃다발 한 개에는 안개꽃 12송이와 장미 3송이가 들어가요. 꽃다발 2개를 만드는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「2개를 만들어도 안개꽃은 장미보다 9송이 더 많아.」","correct":true,"mis_target":"M6-1-u4-X04"},{"t":"나린 — 「안개꽃은 24송이 필요해.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「안개꽃은 언제나 장미의 4배야.」","mis":"M6-1-u4-X16"}],"explanation":["2개이면 안개꽃 24송이, 장미 6송이예요.","차는 24 − 6 = 18로 변해요.","가온은 차가 그대로라고 잘못 말했어요."]}]}}'::jsonb),
('g6_1_math_u4_L02_challenge#4','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C1',3,'ox','auto','주스를 두 병 만들면 물과 원액의 차는 그대로 3컵이에요.',ARRAY['M6-1-u4-X04']::text[],true,'{"seq":4,"concept":"M6-1-u4-C1","difficulty":3,"kind":"ox","stem":"주스를 두 병 만들면 물과 원액의 차는 그대로 3컵이에요.","answer":"X","reason_options":[{"t":"두 병이면 물 8컵, 원액 2컵이라 차는 6컵으로 변하기 때문에","correct":true},{"t":"병 수를 늘려도 차는 변하지 않기 때문에","mis":"M6-1-u4-X04"}],"mis":"M6-1-u4-X04","explanation":["두 양은 뺄셈(차)과 나눗셈(배)으로 비교할 수 있어요.","두 양이 같은 배로 늘면 차는 변해요.","그래도 나눗셈으로 비교한 배는 변하지 않아요."],"variant_rule":{"alt":[{"stem":"팔찌 3개를 만들면 노란 구슬은 파란 구슬보다 24개 더 많아요.","answer":"O","reason_options":[{"t":"노란 구슬 30개, 파란 구슬 6개라 30 − 6 = 24이기 때문에","correct":true},{"t":"팔찌 수를 늘려도 차는 8개 그대로이기 때문에","mis":"M6-1-u4-X04"}],"explanation":["두 양은 뺄셈(차)과 나눗셈(배)으로 비교할 수 있어요.","두 양이 같은 배로 늘면 차는 변해요.","그래도 나눗셈으로 비교한 배는 변하지 않아요."]},{"stem":"가로 5 cm, 세로 2 cm인 직사각형을 모양 그대로 키워 세로가 6 cm가 되면 가로는 9 cm예요.","answer":"X","reason_options":[{"t":"세로가 3배가 되었으니 가로도 3배인 15 cm이기 때문에","correct":true},{"t":"세로가 4 cm 늘었으니 가로도 4 cm 늘기 때문에","mis":"M6-1-u4-X03"}],"explanation":["두 양은 뺄셈(차)과 나눗셈(배)으로 비교할 수 있어요.","두 양이 같은 배로 늘면 차는 변해요.","그래도 나눗셈으로 비교한 배는 변하지 않아요."]}]}}'::jsonb),
('g6_1_math_u4_L02_challenge#5','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C2',3,'mc','auto','우리 반 남학생은 10명, 여학생은 13명이에요. 전체 학생 수에 대한 여학생 수의 비는 어느 것인가요?',ARRAY['M6-1-u4-X07','M6-1-u4-X01','M6-1-u4-X16']::text[],true,'{"seq":5,"concept":"M6-1-u4-C2","difficulty":3,"kind":"mc","stem":"우리 반 남학생은 10명, 여학생은 13명이에요. 전체 학생 수에 대한 여학생 수의 비는 어느 것인가요?","options":[{"t":"13：23","correct":true},{"t":"13：10","mis":"M6-1-u4-X07"},{"t":"23：13","mis":"M6-1-u4-X01"},{"t":"10：23","mis":"M6-1-u4-X16"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 전체 학생 수 10 + 13 = 23이에요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 13：23이에요."],"variant_rule":{"alt":[{"stem":"강아지 9마리 가운데 흰 강아지가 4마리예요. 흰색이 아닌 강아지 수에 대한 흰 강아지 수의 비는 어느 것인가요?","options":[{"t":"4：5","correct":true},{"t":"5：4","mis":"M6-1-u4-X01"},{"t":"4：9","mis":"M6-1-u4-X07"},{"t":"9：4","mis":"M6-1-u4-X07"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 흰색이 아닌 강아지 수 9 − 4 = 5예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 4：5예요."]},{"stem":"주스 8컵 가운데 5컵을 마셨어요. 처음 주스 양에 대한 마신 주스 양의 비는 어느 것인가요?","options":[{"t":"5：8","correct":true},{"t":"8：5","mis":"M6-1-u4-X01"},{"t":"5：3","mis":"M6-1-u4-X07"},{"t":"3：8","mis":"M6-1-u4-X16"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 처음 주스 양이에요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 5：8이에요."]}]}}'::jsonb),
('g6_1_math_u4_L02_challenge#6','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C2',3,'sa','auto','우리 반 남학생은 10명, 여학생은 13명이에요. 여학생 수의 전체 학생 수에 대한 비에서 후항은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C2","difficulty":3,"kind":"sa","stem":"우리 반 남학생은 10명, 여학생은 13명이에요. 여학생 수의 전체 학생 수에 대한 비에서 후항은 얼마인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["후항은 기준량인 전체 학생 수예요.","전체 학생은 10 + 13 = 23(명)이라 비는 13：23이에요.","답은 23이에요."],"mis":"M6-1-u4-X07","variant_rule":{"alt":[{"stem":"바구니에 귤 12개와 사과 5개가 있어요. 전체 과일 수에 대한 귤 수의 비에서 기준량은 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["기준량은 전체 과일 수예요.","전체 과일은 12 + 5 = 17(개)라 비는 12：17이에요.","답은 17이에요."]},{"stem":"학생 30명 가운데 안경을 쓴 학생은 7명이에요. 안경을 쓰지 않은 학생 수의 전체 학생 수에 대한 비에서 전항은 얼마인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["전항은 비교하는 양인 안경을 쓰지 않은 학생 수예요.","30 − 7 = 23(명)이라 비는 23：30이에요.","답은 23이에요."]}]}}'::jsonb),
('g6_1_math_u4_L02_challenge#7','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C2',3,'error','auto','사과 7개와 배 3개가 있어요. 배 수의 사과 수에 대한 비는 무엇일까요? 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X01','M6-1-u4-X16']::text[],true,'{"seq":7,"concept":"M6-1-u4-C2","difficulty":3,"kind":"error","stem":"사과 7개와 배 3개가 있어요. 배 수의 사과 수에 대한 비는 무엇일까요? 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「7：3이야.」","correct":true,"mis_target":"M6-1-u4-X01"},{"t":"이현 — 「기준량은 사과 수야.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「비는 3：7이야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량은 사과 수예요.","비는 (비교하는 양)：(기준량) 차례라 3：7이에요.","준희는 기준량과 비교하는 양을 바꾸어 썼어요."],"variant_rule":{"alt":[{"stem":"치즈 4장과 달걀부침 3개로 샌드위치를 만들었어요. 치즈 수에 대한 달걀부침 수의 비는 무엇일까요? 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「4：3이야.」","correct":true,"mis_target":"M6-1-u4-X01"},{"t":"수아 — 「기준량은 치즈 수야.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「비는 3：4야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량은 치즈 수예요.","비는 (비교하는 양)：(기준량) 차례라 3：4예요.","서호는 기준량과 비교하는 양을 바꾸어 썼어요."]},{"stem":"닭 2마리와 병아리 5마리가 있어요. 닭 수에 대한 병아리 수의 비는 무엇일까요? 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「2：5야.」","correct":true,"mis_target":"M6-1-u4-X01"},{"t":"나린 — 「기준량은 닭 수야.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「비는 5：2야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량은 닭 수예요.","비는 (비교하는 양)：(기준량) 차례라 5：2예요.","가온은 기준량과 비교하는 양을 바꾸어 썼어요."]}]}}'::jsonb),
('g6_1_math_u4_L02_challenge#8','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C1',4,'mc','auto','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 3병을 만들 때의 차와 배를 바르게 말한 것은 어느 것인가요?',ARRAY['M6-1-u4-X04']::text[],true,'{"seq":8,"concept":"M6-1-u4-C1","difficulty":4,"kind":"mc","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 3병을 만들 때의 차와 배를 바르게 말한 것은 어느 것인가요?","options":[{"t":"차는 9컵, 배는 4배","correct":true},{"t":"차는 3컵, 배는 4배","mis":"M6-1-u4-X04"},{"t":"차는 9컵, 배는 12배","mis":"M6-1-u4-X04"},{"t":"차는 3컵, 배는 12배","mis":"M6-1-u4-X04"}],"explanation":["3병이면 물 12컵, 매실 원액 3컵이에요.","차는 12 − 3 = 9예요.","배는 12 ÷ 3 = 4로 그대로예요."],"variant_rule":{"alt":[{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 팔찌 2개를 만들 때의 차와 배를 바르게 말한 것은 어느 것인가요?","options":[{"t":"차는 16개, 배는 5배","correct":true},{"t":"차는 8개, 배는 5배","mis":"M6-1-u4-X04"},{"t":"차는 16개, 배는 10배","mis":"M6-1-u4-X04"},{"t":"차는 8개, 배는 10배","mis":"M6-1-u4-X04"}],"explanation":["2개이면 노란 구슬 20개, 파란 구슬 4개예요.","차는 20 − 4 = 16이에요.","배는 20 ÷ 4 = 5로 그대로예요."]},{"stem":"모닝빵 반죽 한 판에는 밀가루 6컵과 우유 2컵이 들어가요. 모닝빵 반죽 3판을 만들 때의 차와 배를 바르게 말한 것은 어느 것인가요?","options":[{"t":"차는 12컵, 배는 3배","correct":true},{"t":"차는 4컵, 배는 3배","mis":"M6-1-u4-X04"},{"t":"차는 12컵, 배는 9배","mis":"M6-1-u4-X04"},{"t":"차는 4컵, 배는 9배","mis":"M6-1-u4-X04"}],"explanation":["3판이면 밀가루 18컵, 우유 6컵이에요.","차는 18 − 6 = 12예요.","배는 18 ÷ 6 = 3으로 그대로예요."]}]}}'::jsonb),
('g6_1_math_u4_L02_challenge#9','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C2',4,'match','auto','말과 비를 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u4-C2","difficulty":4,"kind":"match","stem":"말과 비를 알맞게 이으세요.","pairs":[{"l":"4에 대한 3의 비","r":"3：4"},{"l":"3의 7에 대한 비","r":"3：7"},{"l":"7 대 4","r":"7：4"}],"mis":"M6-1-u4-X01","explanation":["「○에 대한」 쪽이 기준량이고 ：의 뒤에 써요.","4에 대한 3의 비 → 3：4, 3의 7에 대한 비 → 3：7, 7 대 4 → 7：4예요.","「대」로 읽을 때는 앞의 수부터 써요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 말과 비를 알맞게 이으세요.","pairs":[{"l":"5 대 2","r":"5：2"},{"l":"5에 대한 2의 비","r":"2：5"},{"l":"5의 9에 대한 비","r":"5：9"}],"explanation":["「○에 대한」 쪽이 기준량이고 ：의 뒤에 써요.","5 대 2 → 5：2, 5에 대한 2의 비 → 2：5, 5의 9에 대한 비 → 5：9예요.","「대」로 읽을 때는 앞의 수부터 써요."]},{"stem":"이번에는 다른 보기예요. 말과 비를 알맞게 이으세요.","pairs":[{"l":"6의 1에 대한 비","r":"6：1"},{"l":"1 대 6","r":"1：6"},{"l":"7에 대한 6의 비","r":"6：7"}],"explanation":["「○에 대한」 쪽이 기준량이고 ：의 뒤에 써요.","6의 1에 대한 비 → 6：1, 1 대 6 → 1：6, 7에 대한 6의 비 → 6：7이에요.","「대」로 읽을 때는 앞의 수부터 써요."]}]}}'::jsonb),
('g6_1_math_u4_L02_challenge#10','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C1',4,'essay','teacher','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 주스를 3병 만들 때 물과 원액을 뺄셈과 나눗셈으로 각각 비교하고, 병 수를 늘려도 변하지 않는 비교를 비로 나타내 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u4-C1","difficulty":4,"kind":"essay","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 주스를 3병 만들 때 물과 원액을 뺄셈과 나눗셈으로 각각 비교하고, 병 수를 늘려도 변하지 않는 비교를 비로 나타내 보세요.","answer_guide":{"answer":"예: 3병이면 물 12컵, 원액 3컵이 필요하다. 뺄셈으로 비교하면 12 − 3 = 9이므로 물이 9컵 더 많다(한 병일 때의 3컵에서 변했다). 나눗셈으로 비교하면 12 ÷ 3 = 4이므로 물은 원액의 4배이다. 병 수를 늘려도 4배는 변하지 않으므로 원액 양에 대한 물 양의 비는 4：1이다.","scoring_points":["3병일 때 물 12컵·원액 3컵을 구했는가","차 9컵과 4배를 각각 구하고 차는 변하지만 배는 그대로임을 밝혔는가","원액 양에 대한 물 양의 비를 4：1로 나타냈는가"]},"explanation":["3병이면 물 12컵, 원액 3컵이에요.","차는 9컵으로 변하지만 배는 4배 그대로예요.","원액 양에 대한 물 양의 비는 4：1이에요."]}'::jsonb),
('g6_1_math_u4_L03_basic#1','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',1,'sa','auto','비 9：50에서 기준량은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u4-C3","difficulty":1,"kind":"sa","stem":"비 9：50에서 기준량은 얼마인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","9：50에서 전항은 9, 후항은 50이에요.","그래서 기준량은 50이에요."],"mis":"M6-1-u4-X01","variant_rule":{"alt":[{"stem":"비 12：5에서 비교하는 양은 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","12：5에서 전항은 12, 후항은 5예요.","그래서 비교하는 양은 12예요."]},{"stem":"비 3：10에서 후항은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","3：10에서 전항은 3, 후항은 10이에요.","그래서 후항은 10이에요."]}]}}'::jsonb),
('g6_1_math_u4_L03_basic#2','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',1,'mc','auto','비 3：10의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X16']::text[],true,'{"seq":2,"concept":"M6-1-u4-C3","difficulty":1,"kind":"mc","stem":"비 3：10의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.3","correct":true},{"t":"3","mis":"M6-1-u4-X15"},{"t":"0.03","mis":"M6-1-u4-X15"},{"t":"0.7","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","3：10의 비율은 3 ÷ 10 = 0.3이에요.","분수로는 ⟨3/10⟩, 소수로는 0.3이에요."],"variant_rule":{"alt":[{"stem":"비 1：4의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.25","correct":true},{"t":"4","mis":"M6-1-u4-X05"},{"t":"2.5","mis":"M6-1-u4-X15"},{"t":"0.025","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","1：4의 비율은 1 ÷ 4 = 0.25예요.","분수로는 ⟨1/4⟩, 소수로는 0.25예요."]},{"stem":"비 6：5의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"1.2","correct":true},{"t":"12","mis":"M6-1-u4-X15"},{"t":"0.12","mis":"M6-1-u4-X15"},{"t":"2.2","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","6：5의 비율은 6 ÷ 5 = 1.2예요.","분수로는 ⟨6/5⟩, 소수로는 1.2예요."]}]}}'::jsonb),
('g6_1_math_u4_L03_basic#3','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',1,'mc','auto','비 9：50을 비율로 나타낸 분수로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X07','M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C3","difficulty":1,"kind":"mc","stem":"비 9：50을 비율로 나타낸 분수로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨9/50⟩","correct":true},{"t":"⟨50/9⟩","mis":"M6-1-u4-X05"},{"t":"⟨9/59⟩","mis":"M6-1-u4-X07"},{"t":"⟨41/50⟩","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","비교하는 양은 9, 기준량은 50이에요.","그래서 비율은 ⟨9/50⟩예요."],"variant_rule":{"alt":[{"stem":"비 3：10을 비율로 나타낸 분수로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨3/10⟩","correct":true},{"t":"⟨10/3⟩","mis":"M6-1-u4-X05"},{"t":"⟨3/13⟩","mis":"M6-1-u4-X07"},{"t":"⟨7/10⟩","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","비교하는 양은 3, 기준량은 10이에요.","그래서 비율은 ⟨3/10⟩이에요."]},{"stem":"비 7：20을 비율로 나타낸 분수로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨7/20⟩","correct":true},{"t":"⟨20/7⟩","mis":"M6-1-u4-X05"},{"t":"⟨7/27⟩","mis":"M6-1-u4-X07"},{"t":"⟨13/20⟩","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","비교하는 양은 7, 기준량은 20이에요.","그래서 비율은 ⟨7/20⟩이에요."]}]}}'::jsonb),
('g6_1_math_u4_L03_basic#4','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',1,'sa','auto','비 6：5의 비율을 소수로 나타내면 1.□예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u4-C3","difficulty":1,"kind":"sa","stem":"비 6：5의 비율을 소수로 나타내면 1.□예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","6：5의 비율은 6 ÷ 5 = 1.2예요.","그래서 □는 2예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"비 3：5의 비율을 소수로 나타내면 0.□예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","3：5의 비율은 3 ÷ 5 = 0.6이에요.","그래서 □는 6이에요."]},{"stem":"비 7：5의 비율을 소수로 나타내면 1.□예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","7：5의 비율은 7 ÷ 5 = 1.4예요.","그래서 □는 4예요."]}]}}'::jsonb),
('g6_1_math_u4_L03_basic#5','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',2,'mc','auto','비 12：5의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X15']::text[],true,'{"seq":5,"concept":"M6-1-u4-C3","difficulty":2,"kind":"mc","stem":"비 12：5의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"2.4","correct":true},{"t":"24","mis":"M6-1-u4-X15"},{"t":"0.24","mis":"M6-1-u4-X15"},{"t":"3.4","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","12：5의 비율은 12 ÷ 5 = 2.4예요.","분수로는 ⟨12/5⟩, 소수로는 2.4예요."],"variant_rule":{"alt":[{"stem":"비 9：50의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.18","correct":true},{"t":"1.8","mis":"M6-1-u4-X15"},{"t":"0.018","mis":"M6-1-u4-X15"},{"t":"0.82","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","9：50의 비율은 9 ÷ 50 = 0.18이에요.","분수로는 ⟨9/50⟩, 소수로는 0.18이에요."]},{"stem":"비 7：4의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"1.75","correct":true},{"t":"17.5","mis":"M6-1-u4-X15"},{"t":"0.175","mis":"M6-1-u4-X15"},{"t":"2.75","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","7：4의 비율은 7 ÷ 4 = 1.75예요.","분수로는 ⟨7/4⟩, 소수로는 1.75예요."]}]}}'::jsonb),
('g6_1_math_u4_L03_basic#6','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',2,'mc','auto','집에서 할머니 댁까지는 20 km, 집에서 주유소까지는 8 km예요. 집과 할머니 댁 사이 거리에 대한 집과 주유소 사이 거리의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X16','M6-1-u4-X15']::text[],true,'{"seq":6,"concept":"M6-1-u4-C3","difficulty":2,"kind":"mc","stem":"집에서 할머니 댁까지는 20 km, 집에서 주유소까지는 8 km예요. 집과 할머니 댁 사이 거리에 대한 집과 주유소 사이 거리의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.4","correct":true},{"t":"2.5","mis":"M6-1-u4-X05"},{"t":"0.6","mis":"M6-1-u4-X16"},{"t":"4","mis":"M6-1-u4-X15"}],"explanation":["기준량은 20, 비교하는 양은 8이에요.","8 ÷ 20 = 0.4예요.","그래서 비율은 0.4예요."],"variant_rule":{"alt":[{"stem":"가로 40 cm, 세로 24 cm인 태극기 액자가 있어요. 가로에 대한 세로의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.6","correct":true},{"t":"0.4","mis":"M6-1-u4-X16"},{"t":"6","mis":"M6-1-u4-X15"},{"t":"0.06","mis":"M6-1-u4-X15"}],"explanation":["기준량은 40, 비교하는 양은 24예요.","24 ÷ 40 = 0.6이에요.","그래서 비율은 0.6이에요."]},{"stem":"마을 자전거 도로 15 km 가운데 12 km가 완성되었어요. 전체 길이에 대한 완성된 길이의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"1.25","mis":"M6-1-u4-X05"},{"t":"0.2","mis":"M6-1-u4-X16"},{"t":"8","mis":"M6-1-u4-X15"}],"explanation":["기준량은 15, 비교하는 양은 12예요.","12 ÷ 15 = 0.8이에요.","그래서 비율은 0.8이에요."]}]}}'::jsonb),
('g6_1_math_u4_L03_basic#7','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',2,'ox','auto','비율은 언제나 1보다 작아요.',ARRAY['M6-1-u4-X06']::text[],true,'{"seq":7,"concept":"M6-1-u4-C3","difficulty":2,"kind":"ox","stem":"비율은 언제나 1보다 작아요.","answer":"X","reason_options":[{"t":"12：5의 비율 2.4처럼 비교하는 양이 더 크면 1보다 크기 때문에","correct":true},{"t":"비율은 전체의 일부만 나타내기 때문에","mis":"M6-1-u4-X06"}],"mis":"M6-1-u4-X06","explanation":["기준량에 대한 비교하는 양의 크기를 비율이라고 해요.","비율 = (비교하는 양) ÷ (기준량) — 분수로도 소수로도 나타내요.","기준량이 달라도 관계가 같으면 비율이 같아요."],"variant_rule":{"alt":[{"stem":"15：25와 30：50은 비율이 같아요.","answer":"O","reason_options":[{"t":"15 ÷ 25 = 0.6이고 30 ÷ 50 = 0.6이기 때문에","correct":true},{"t":"두 비 모두 전항이 후항보다 작기 때문에","mis":"M6-1-u4-X11"}],"explanation":["기준량에 대한 비교하는 양의 크기를 비율이라고 해요.","비율 = (비교하는 양) ÷ (기준량) — 분수로도 소수로도 나타내요.","기준량이 달라도 관계가 같으면 비율이 같아요."]},{"stem":"⟨3/10⟩과 0.3은 같은 비율이에요.","answer":"O","reason_options":[{"t":"⟨3/10⟩ = 0.3이기 때문에","correct":true},{"t":"두 수에 모두 3이 들어 있기 때문에","mis":"M6-1-u4-X15"}],"explanation":["기준량에 대한 비교하는 양의 크기를 비율이라고 해요.","비율 = (비교하는 양) ÷ (기준량) — 분수로도 소수로도 나타내요.","기준량이 달라도 관계가 같으면 비율이 같아요."]}]}}'::jsonb),
